/* DAWAH X — ahmad, অধ্যায় 74 · খণ্ড 74 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][74]=[[14601,14601,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏ذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَذْبَحَ قَالَ اذْبَحْ وَلَا حَرَجَ ‏","","",""],[14602,14602,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَهْلِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَهْلٍ ‏ ‏أَخُو ‏ ‏بَنِي حَارِثَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏مَرْحَبٌ ‏ ‏الْيَهُودِيُّ مِنْ حِصْنِهِمْ قَدْ جَمَعَ سِلَاحَهُ ‏ ‏يَرْتَجِزُ ‏ ‏وَيَقُولُ ‏ ‏قَدْ عَلِمَتْ ‏ ‏خَيْبَرُ ‏ ‏أَنِّي ‏ ‏مَرْحَبُ ‏ ‏شَاكِي ‏ ‏السِّلَاحِ بَطَلٌ مُجَرَّبُ ‏ ‏أَطْعَنُ أَحْيَانًا وَحِينًا أَضْرِبُ ‏ ‏إِذَا اللُّيُوثُ أَقْبَلَتْ ‏ ‏تَلَهَّبُ ‏ ‏كَانَ حِمَايَ لَحِمًى لَا يُقْرَبُ ‏ ‏وَهُوَ يَقُولُ مَنْ مُبَارِزٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لِهَذَا فَقَالَ ‏ ‏مُحَمَّدُ ابْنُ مَسْلَمَةَ ‏ ‏أَنَا لَهُ يَا رَسُولَ اللَّهِ وَأَنَا وَاللَّهِ ‏ ‏الْمَوْتُورُ ‏ ‏الثَّائِرُ قَتَلُوا أَخِي بِالْأَمْسِ قَالَ ‏ ‏فَقُمْ إِلَيْهِ اللَّهُمَّ أَعِنْهُ عَلَيْهِ فَلَمَّا ‏ ‏دَنَا ‏ ‏أَحَدُهُمَا مِنْ صَاحِبِهِ دَخَلَتْ بَيْنَهُمَا شَجَرَةٌ ‏ ‏عُمْرِيَّةٌ مِنْ شَجَرِ ‏ ‏الْعُشَرِ ‏ ‏فَجَعَلَ أَحَدُهُمَا ‏ ‏يَلُوذُ ‏ ‏بِهَا مِنْ صَاحِبِهِ كُلَّمَا لَاذَ بِهَا مِنْهُ اقْتَطَعَ بِسَيْفِهِ مَا دُونَهُ حَتَّى بَرَزَ كُلُّ وَاحِدٍ مِنْهُمَا لِصَاحِبِهِ وَصَارَتْ بَيْنَهُمَا كَالرَّجُلِ الْقَائِمِ مَا فِيهَا ‏ ‏فَنَنٌ ‏ ‏ثُمَّ حَمَلَ ‏ ‏مَرْحَبٌ ‏ ‏عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏فَضَرَبَهُ فَاتَّقَى ‏ ‏بِالدَّرَقَةِ ‏ ‏فَوَقَعَ سَيْفُهُ فِيهَا فَعَضَّتْ بِهِ فَأَمْسَكَتْهُ وَضَرَبَهُ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏حَتَّى قَتَلَهُ ‏","","",""],[14603,14603,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏الْأَهْلِيَّةُ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏وَأَذِنَ فِي لُحُومِ الْخَيْلِ ‏","","",""],[14604,14604,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تَقْسِمُوهَا فَإِنَّهُ مَنْ ‏ ‏أَعْمَرَ ‏ ‏عُمْرَى ‏ ‏فَهِيَ لِلَّذِي ‏ ‏أَعْمَرَهَا ‏ ‏حَيًّا وَمَيِّتًا ‏ ‏وَلِعَقِبِهِ ‏ ‏تَقْسِمُوهَا ‏","","",""],[14605,14605,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُرْسِلُوا ‏ ‏فَوَاشِيَكُمْ ‏ ‏وَصِبْيَانَكُمْ إِذَا غَابَتْ الشَّمْسُ حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ فَإِنَّ الشَّيَاطِينَ تَعْبَثُ إِذَا غَابَتْ الشَّمْسُ حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ ‏","","",""],[14606,14606,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏فَقَالَ ‏ ‏بَعْضُ الْقَوْمِ ‏ ‏لِأَبِي الزُّبَيْرِ ‏ ‏وَأَنَا أَسْمَعُ الْمَكْتُوبَةَ ‏ ‏قَالَ ‏ ‏الْمَكْتُوبَةُ وَغَيْرُ الْمَكْتُوبَةِ ‏","","",""],[14607,14607,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَكَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُحُومَ الْأَضَاحِيِّ وَتَزَوَّدْنَا حَتَّى بَلَغْنَا بِهَا ‏ ‏الْمَدِينَةَ ‏","","",""],[14608,14608,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ لِي ‏ ‏جَارِيَةً ‏ ‏وَهِيَ خَادِمُنَا ‏ ‏وَسَايِسَتُنَا أَطُوفُ عَلَيْهَا وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ فَقَالَ ‏ ‏اعْزِلْ ‏ ‏عَنْهَا إِنْ شِئْتَ فَإِنَّهُ ‏ ‏سَيَأْتِيهَا مَا قُدِّرَ لَهَا قَالَ فَلَبِثَ الرَّجُلُ ثُمَّ أَتَاهُ فَقَالَ إِنَّ ‏ ‏الْجَارِيَةَ ‏ ‏قَدْ حَمَلَتْ قَالَ قَدْ أَخْبَرْتُكَ أَنَّهُ ‏ ‏سَيَأْتِيهَا مَا قُدِّرَ لَهَا ‏","","",""],[14609,14609,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيعُ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏دَعُوا النَّاسَ يَرْزُقُ اللَّهُ بَعْضَهُمْ مِنْ بَعْضٍ ‏ ‏حَدَّثَنَاه ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[14610,14610,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[14611,14611,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رُمِيَ ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏ ‏فِي ‏ ‏أَكْحَلِهِ ‏ ‏فَحَسَمَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ ‏ ‏بِمِشْقَصٍ ‏ ‏قَالَ ثُمَّ وَرِمَتْ قَالَ ‏ ‏فَحَسَمَهُ ‏ ‏الثَّانِيَةَ ‏","","",""],[14612,14612,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَغْلِقُوا الْأَبْوَابَ ‏ ‏وَأَوْكِئُوا ‏ ‏الْأَسْقِيَةَ ‏ ‏وَخَمِّرُوا ‏ ‏الْإِنَاءَ وَأَطْفِئُوا ‏ ‏السُّرُجَ ‏ ‏فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ غُلُقًا وَلَا يَحُلُّ ‏ ‏وِكَاءً ‏ ‏وَلَا يَكْشِفُ إِنَاءً فَإِنَّ ‏ ‏الْفُوَيْسِقَةَ ‏ ‏تُضْرِمُ ‏ ‏عَلَى أَهْلِ الْبَيْتِ ‏","","",""],[14613,14613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ وَلَا مُسْلِمَةٍ وَلَا مُؤْمِنٍ وَلَا مُؤْمِنَةٍ يَمْرَضُ مَرَضًا إِلَّا حَطَّ اللَّهُ عَنْهُ مِنْ خَطَايَاهُ ‏","","",""],[14614,14614,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ سَوَادَةَ ‏ ‏أَنَّ ‏ ‏مَوْلًى لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِمْ وَهُمْ يَجْتَنُونَ أَرَاكًا فَأَعْطَاهُ رَجُلٌ جَنْيَ أَرَاكٍ فَقَالَ ‏ ‏لَوْ كُنْتُ مُتَوَضِّئًا أَكَلْتُهُ ‏","","",""],[14615,14615,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ثَمَنِ الْكَلْبِ ‏ ‏وَالسِّنَّوْرِ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ عَنْ ذَلِكَ ‏","","",""],[14616,14616,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏بَنِي مَخْزُومٍ ‏ ‏سَرَقَتْ فَعَاذَتْ ‏ ‏بِأُسَامَةَ بْنِ زَيْدٍ ‏ ‏حِبِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُتِيَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ كَانَتْ ‏ ‏فَاطِمَةَ ‏ ‏لَقَطَعْتُ يَدَهَا فَقَطَعَهَا ‏","","",""],[14617,14617,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ ‏ ‏طَلَّقَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ فَأَتَى ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُرَاجِعْهَا فَإِنَّهَا امْرَأَتُهُ ‏","","",""],[14618,14618,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ رَجَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ ‏ ‏رَجَمَ رَجُلًا مِنْ ‏ ‏أَسْلَمَ ‏ ‏وَرَجُلًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏وَامْرَأَةً وَقَالَ لِلْيَهُودِيِّ نَحْنُ نَحْكُمُ عَلَيْكُمْ الْيَوْمَ ‏","","",""],[14619,14619,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏زَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَصِلَ الْمَرْأَةُ بِرَأْسِهَا شَيْئًا ‏","","",""],[14620,14620,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ ‏","","",""],[14621,14621,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ مَثَلُ السُّنْبُلَةِ تَسْتَقِيمُ مَرَّةً وَتَخِرُّ مَرَّةً وَمَثَلُ الْكَافِرِ مَثَلُ الْأَرْزَةِ لَا تَزَالُ مُسْتَقِيمَةً حَتَّى تَخِرَّ وَلَا تَشْعُرُ ‏","","",""],[14622,14622,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏كَمْ طَافَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقَالَ مَرَّةً وَاحِدَةً ‏","","",""],[14623,14623,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكِتَابٍ أَصَابَهُ مِنْ بَعْضِ أَهْلِ الْكُتُبِ فَقَرَأَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَغَضِبَ فَقَالَ أَمُتَهَوِّكُونَ فِيهَا يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ جِئْتُكُمْ بِهَا بَيْضَاءَ نَقِيَّةً لَا تَسْأَلُوهُمْ عَنْ شَيْءٍ فَيُخْبِرُوكُمْ بِحَقٍّ فَتُكَذِّبُوا بِهِ أَوْ بِبَاطِلٍ فَتُصَدِّقُوا بِهِ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ حَيًّا مَا وَسِعَهُ إِلَّا أَنْ يَتَّبِعَنِي ‏","","",""],[14624,14624,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَمَّارٍ الدُّهْنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ يَوْمَ الْفَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ ‏","","",""],[14625,14625,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا لَحْمَ الصَّيْدِ وَأَنْتُمْ حُرُمٌ مَا لَمْ تَصِيدُوهُ أَوْ يُصَدْ لَكُمْ ‏","","",""],[14626,14626,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى زَمَنَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ الْبَصَلِ وَالْكُرَّاثِ فَأَكَلَهُمَا قَوْمٌ ثُمَّ جَاءُوا إِلَى الْمَسْجِدِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ أَنْهَ عَنْ هَاتَيْنِ الشَّجَرَتَيْنِ الْمُنْتِنَتَيْنِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ وَلَكِنْ أَجْهَدَنَا الْجُوعُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَهُمَا فَلَا يَحْضُرْ مَسْجِدَنَا فَإِنَّ الْمَلَائِكَةَ ‏ ‏تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ بَنُو ‏ ‏آدَمَ ‏","","",""],[14627,14627,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي مُلْتَحِفًا فِي ثَوْبٍ وَاحِدٍ وَرِدَاؤُهُ مَوْضُوعٌ فَقُلْنَا لَهُ تُصَلِّي فِي ثَوْبٍ وَاحِدٍ وَرِدَاؤُكَ مَوْضُوعٌ قَالَ لِيَدْخُلَ عَلَيَّ مِثْلُكَ ‏ ‏فَيَرَانِي ‏ ‏أُصَلِّي فِي ثَوْبٍ وَاحِدٍ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي هَكَذَا ‏","","",""],[14628,14628,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّهَا الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّهَا الْمُقَدَّمُ يَا مَعْشَرَ النِّسَاءِ إِذَا سَجَدَ الرِّجَالُ فَاغْضُضْنَ أَبْصَارَكُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏","","",""],[14629,14629,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَشَيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَذَبَحَتْ لَنَا شَاةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدْخُلَنَّ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَدَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ لَيَدْخُلَنَّ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَدَخَلَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ لَيَدْخُلَنَّ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَقَالَ اللَّهُمَّ إِنْ شِئْتَ فَاجْعَلْهُ ‏ ‏عَلِيًّا ‏ ‏فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏ثُمَّ أُتِينَا بِطَعَامٍ فَأَكَلْنَا فَقُمْنَا إِلَى صَلَاةِ الظُّهْرِ وَلَمْ يَتَوَضَّأْ أَحَدٌ مِنَّا ثُمَّ أُتِينَا بِبَقِيَّةِ الطَّعَامِ ثُمَّ قُمْنَا إِلَى الْعَصْرِ وَمَا مَسَّ أَحَدٌ مِنَّا مَاءً ‏","","",""],[14630,14630,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَقَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏فَطُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحِلُّوا وَاجْعَلُوهَا عُمْرَةً إِلَّا مَنْ سَاقَ ‏ ‏الْهَدْيَ ‏ ‏قَالَ فَسَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏وَوَقَعَتْ النِّسَاءُ فَلَمَّا كَانَ يَوْمُ ‏ ‏التَّرْوِيَةِ ‏ ‏أَهْلَلْنَا ‏ ‏بِالْحَجِّ قَالَ ‏ ‏سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ ‏ ‏يَا رَسُولَ اللَّهِ عُمْرَتُنَا هَذِهِ أَلِعَامِنَا أَمْ لِلْأَبَدِ قَالَ لَا بَلْ لِلْأَبَدِ ‏","","",""],[14631,14631,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ عِشْتُ إِنْ شَاءَ اللَّهُ نَهَيْتُ أَنْ يُسَمَّى بَرَكَةُ وَيَسَارٌ ‏","","",""],[14632,14632,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِابْنِ صَائِدٍ ‏ ‏مَا ‏ ‏تَرَى قَالَ أَرَى عَرْشًا عَلَى الْمَاءِ ‏ ‏أَوْ قَالَ عَلَى الْبَحْرِ ‏ ‏حَوْلَهُ حَيَّاتٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاكَ عَرْشُ إِبْلِيسَ ‏","","",""],[14633,14633,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَلَمَّا رَجَعْتُ سَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ فَلَمَّا فَرَغَ قُلْتُ يَا رَسُولَ اللَّهِ سَلَّمْتُ عَلَيْكَ فَلَمْ تَرُدَّ عَلَيَّ قَالَ ‏ ‏إِنِّي كُنْتُ أُصَلِّي وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏مُتَوَجِّهًا لِغَيْرِ الْقِبْلَةِ ‏","","",""],[14634,14634,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمِّرُوا ‏ ‏الْآنِيَةَ ‏ ‏وَأَوْكِئُوا ‏ ‏الْأَسْقِيَةَ ‏ ‏وَأَجِيفُوا ‏ ‏الْبَابَ وَأَطْفِئُوا الْمَصَابِيحَ عِنْدَ الرُّقَادِ فَإِنَّ ‏ ‏الْفُوَيْسِقَةَ ‏ ‏رُبَّمَا اجْتَرَّتْ الْفَتِيلَةَ فَأَحْرَقَتْ الْبَيْتَ ‏ ‏وَأَكْفِتُوا ‏ ‏صِبْيَانَكُمْ عِنْدَ الْمَسَاءِ فَإِنَّ لِلْجِنِّ انْتِشَارًا وَخَطْفَةً ‏","","",""],[14635,14635,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ أَكْلِ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ ثُمَّ قَالَ بَعْدَ ذَلِكَ كُلُوا وَتَزَوَّدُوا وَادَّخِرُوا ‏","","",""],[14636,14636,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏مِنْ الْحَجَرِ الْأَسْوَدِ حَتَّى انْتَهَى إِلَيْهِ ثَلَاثَةَ أَطْوَافٍ ‏","","",""],[14637,14637,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏خَرَجَ مِنْ الْمَسْجِدِ وَهُوَ يُرِيدُ ‏ ‏الصَّفَا ‏ ‏وَهُوَ يَقُولُ نَبْدَأُ بِمَا بَدَأَ اللَّهُ عَزَّ وَجَلَّ بِهِ ‏","","",""],[14638,14638,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا وَقَفَ عَلَى ‏ ‏الصَّفَا ‏ ‏يُكَبِّرُ ثَلَاثًا وَيَقُولُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏يَصْنَعُ ذَلِكَ ثَلَاثَ مَرَّاتٍ وَيَدْعُو وَيَصْنَعُ عَلَى ‏ ‏الْمَرْوَةِ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[14639,14639,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا نَزَلَ مِنْ ‏ ‏الصَّفَا ‏ ‏مَشَى حَتَّى إِذَا ‏ ‏انْصَبَّتْ ‏ ‏قَدَمَاهُ فِي ‏ ‏بَطْنِ الْوَادِي ‏ ‏سَعَى حَتَّى يَخْرُجَ مِنْهُ ‏","","",""],[14640,14640,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحَرَ بَعْضَ ‏ ‏هَدْيِهِ ‏ ‏بِيَدِهِ وَبَعْضُهُ نَحَرَهُ غَيْرُهُ ‏","","",""],[14641,14641,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ لِي ‏ ‏جَارِيَةً ‏ ‏وَأَنَا ‏ ‏أَعْزِلُ ‏ ‏عَنْهَا فَقَالَ لَهُ مَا يُقَدَّرْ يَكُنْ فَلَمْ يَلْبَثْ أَنْ حَمَلَتْ فَجَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا نَبِيَّ اللَّهِ أَلَمْ تَرَ أَنَّهَا حَمَلَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَضَى اللَّهُ لِنَفْسٍ أَنْ تَخْرُجَ إِلَّا هِيَ ‏ ‏كَائِنَةٌ ‏","","",""],[14642,14642,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَةٍ فَجِئْتُ وَهُوَ ‏ ‏يُصَلِّي نَحْوَ الْمَشْرِقِ ‏ ‏وَيُومِئُ ‏ ‏إِيمَاءً ‏ ‏عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏السُّجُودُ أَخْفَضُ مِنْ الرُّكُوعِ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ قَالَ فَلَمَّا قَضَى صَلَاتَهُ قَالَ مَا فَعَلْتَ فِي حَاجَةِ كَذَا وَكَذَا ‏ ‏إِنِّي كُنْتُ أُصَلِّي ‏","","",""],[14643,14643,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُعْطُوهَا أَحَدًا فَمَنْ أُعْمِرَ شَيْئًا فَهُوَ لَهُ ‏","","",""],[14644,14644,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ التَّمْرِ وَالزَّبِيبِ وَالرُّطَبِ ‏ ‏وَالْبُسْرِ ‏ ‏يَعْنِي أَنَّ ‏ ‏يُنْبَذَا ‏","","",""],[14645,14645,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ أَحَدُكُمْ فَلْيَعْتَدِلْ وَلَا يَفْتَرِشْ ذِرَاعَيْهِ افْتِرَاشَ الْكَلْبِ ‏","","",""],[14646,14646,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ خَافَ مِنْكُمْ أَنْ لَا يَسْتَيْقِظَ مِنْ آخِرِ اللَّيْلِ ‏ ‏فَلْيُوتِرْ ‏ ‏مِنْ أَوَّلِ اللَّيْلِ ثُمَّ لِيَرْقُدْ وَمَنْ طَمِعَ مِنْكُمْ أَنْ يَسْتَيْقِظَ مِنْ آخِرِ اللَّيْلِ ‏ ‏فَلْيُوتِرْ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَإِنَّ قِرَاءَةَ آخِرِ اللَّيْلِ ‏ ‏مَحْضُورَةٌ ‏ ‏وَذَلِكَ أَفْضَلُ ‏","","",""],[14647,14647,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏السُّلَيْكِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ إِلَى الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ فَلْيُصَلِّ رَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[14648,14648,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَلَمَّا كَانَ يَوْمُ النَّحْرِ لَمْ نَقْرَبْ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏","","",""],[14649,14649,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏فَقَالَ رَجُلٌ أَنَا رَأَيْتُ ‏ ‏ابْنَ جَابِرٍ ‏ ‏يَطْلُبُ أَرْضًا ‏ ‏مُخَابَرَةً ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏انْظُرُوا إِلَى هَذَا إِنَّ أَبَاهُ يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ وَهُوَ يَطْلُبُ أَرْضًا ‏ ‏يُخَابِرُ ‏ ‏بِهَا ‏","","",""],[14650,14650,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ ‏ ‏أَوْ الْكُفْرِ ‏ ‏تَرْكُ الصَّلَاةِ ‏","","",""],[14651,14651,"","","‏ ‏و سَمِعْت ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تُبَاشِرْ ‏ ‏الْمَرْأَةُ الْمَرْأَةَ فِي الثَّوْبِ الْوَاحِدِ وَلَا ‏ ‏يُبَاشِرْ ‏ ‏الرَّجُلُ الرَّجُلَ فِي الثَّوْبِ الْوَاحِدِ ‏ ‏قَالَ ‏ ‏فَقُلْنَا ‏ ‏لِجَابِرٍ ‏ ‏أَكُنْتُمْ تَعُدُّونَ الذُّنُوبَ شِرْكًا قَالَ ‏ ‏مَعَاذَ اللَّهِ ‏","","",""],[14652,14652,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏ثِقَةٌ مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَحْمُ الصَّيْدِ حَلَالٌ لِلْمُحْرِمِ مَا لَمْ يَصِدْهُ أَوْ يُصَدْ لَهُ ‏","","",""],[14653,14653,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بَشِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعْضِ أَهْلِهِ فَقَالَ هَلْ عِنْدَكُمْ مِنْ ‏ ‏إِدَامٍ ‏ ‏فَقَالُوا لَا إِلَّا شَيْءٌ مِنْ خَلٍّ فَقَالَ هَلُمُّوا فَجَعَلَ يَصْطَبِغُ بِهِ وَيَقُولُ ‏ ‏نِعْمَ ‏ ‏الْإِدَامُ ‏ ‏الْخَلُّ ‏","","",""],[14654,14654,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَا بَيْنَ مِنْبَرِي إِلَى حُجْرَتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَإِنَّ مِنْبَرِي عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ ‏","","",""],[14655,14655,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نُصِيبُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَغَانِمِنَا مِنْ الْمُشْرِكِينَ الْأَسْقِيَةَ وَالْأَوْعِيَةَ فَيَقْسِمُهَا وَكُلُّهَا مَيْتَةٌ ‏","","",""],[14656,14656,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيتُنِي دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا ‏ ‏بِالرُّمَيْصَاءِ ‏ ‏امْرَأَةِ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَسَمِعْتُ ‏ ‏خَشْفَةً ‏ ‏أَمَامِي قُلْتُ مَنْ هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا ‏ ‏بِلَالٌ ‏ ‏قَالَ وَرَأَيْتُ قَصْرًا أَبْيَضَ ‏ ‏بِفِنَائِهِ ‏ ‏جَارِيَةٌ ‏ ‏فَقُلْتُ لِمَنْ هَذَا الْقَصْرُ قَالَتْ هَذَا ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَأَرَدْتُ أَنْ أَدْخُلَهُ فَأَنْظُرَ إِلَيْهِ فَذَكَرْتُ غَيْرَتَكَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ أَوَعَلَيْكَ أَغَارُ ‏","","",""],[14657,14657,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَاتَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحَارِبَ بْنَ خَصَفَةَ ‏ ‏فَجَاءَ رَجُلٌ مِنْهُمْ يُقَالُ لَهُ ‏ ‏غَوْرَثُ بْنُ الْحَارِثِ ‏ ‏حَتَّى قَامَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالسَّيْفِ فَقَالَ مَنْ يَمْنَعُكَ مِنِّي قَالَ اللَّهُ عَزَّ وَجَلَّ فَسَقَطَ السَّيْفُ مِنْ يَدِهِ فَأَخَذَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ يَمْنَعُكَ مِنِّي قَالَ كُنْ كَخَيْرِ آخِذٍ قَالَ أَتَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ قَالَ لَا وَلَكِنْ أُعَاهِدُكَ عَلَى أَنْ لَا أُقَاتِلَكَ وَلَا أَكُونَ مَعَ قَوْمٍ يُقَاتِلُونَكَ فَخَلَّى سَبِيلَهُ فَأَتَى قَوْمَهُ فَقَالَ جِئْتُكُمْ مِنْ عِنْدِ خَيْرِ النَّاسِ فَلَمَّا حَضَرَتْ الصَّلَاةُ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ فَكَانَ النَّاسُ طَائِفَتَيْنِ طَائِفَةً ‏ ‏بِإِزَاءِ ‏ ‏الْعَدُوِّ وَطَائِفَةً صَلَّوْا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِالطَّائِفَةِ الَّذِينَ مَعَهُ رَكْعَتَيْنِ وَانْصَرَفُوا فَكَانُوا بِمَكَانِ أُولَئِكَ الَّذِينَ ‏ ‏بِإِزَاءِ ‏ ‏عَدُوِّهِمْ وَانْصَرَفَ الَّذِينَ ‏ ‏بِإِزَاءِ ‏ ‏عَدُوِّهِمْ فَصَلَّوْا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ فَكَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ رَكَعَاتٍ وَلِلْقَوْمِ رَكْعَتَيْنِ رَكْعَتَيْنِ ‏","","",""],[14658,14658,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ يَعْنِي ابْنَ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ أَهْلَهُ ‏ ‏الْإِدَامَ ‏ ‏قَالُوا مَا عِنْدَنَا إِلَّا الْخَلُّ قَالَ فَدَعَا بِهِ فَجَعَلَ يَأْكُلُ بِهِ وَيَقُولُ ‏ ‏نِعْمَ ‏ ‏الْإِدَامُ ‏ ‏الْخَلُّ نِعْمَ ‏ ‏الْإِدَامُ ‏ ‏الْخَلُّ ‏","","",""],[14659,14659,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ نَفْسَهُ عَلَى النَّاسِ بِالْمَوْقِفِ فَيَقُولُ ‏ ‏هَلْ مِنْ رَجُلٍ يَحْمِلُنِي إِلَى قَوْمِهِ فَإِنَّ ‏ ‏قُرَيْشًا ‏ ‏قَدْ مَنَعُونِي أَنْ أُبَلِّغَ كَلَامَ رَبِّي عَزَّ وَجَلَّ فَأَتَاهُ رَجُلٌ مِنْ ‏ ‏هَمْدَانَ ‏ ‏فَقَالَ مِمَّنْ أَنْتَ فَقَالَ الرَّجُلُ مِنْ ‏ ‏هَمْدَانَ ‏ ‏قَالَ فَهَلْ عِنْدَ قَوْمِكَ مِنْ مَنَعَةٍ قَالَ نَعَمْ ثُمَّ إِنَّ الرَّجُلَ خَشِيَ أَنْ يَحْقِرَهُ قَوْمُهُ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ آتِيهِمْ فَأُخْبِرُهُمْ ثُمَّ ‏ ‏آتِيكَ مِنْ عَامٍ قَابِلٍ قَالَ نَعَمْ فَانْطَلَقَ وَجَاءَ وَفْدُ ‏ ‏الْأَنْصَارِ ‏ ‏فِي رَجَبٍ ‏","","",""],[14660,14660,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏تَزَوَّجْتُ فَقَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَزَوَّجْتَ قَالَ قُلْتُ تَزَوَّجْتُ ‏ ‏ثَيِّبًا ‏ ‏فَقَالَ ‏ ‏مَا لَكَ وَلِلْعَذَارَى وَلِعَابِهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِعَمْرِو بْنِ دِينَارٍ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَهَلَّا ‏ ‏جَارِيَةً ‏ ‏تُلَاعِبُهَا وَتُلَاعِبُكَ ‏ ‏حَدَّثَنَاهُمَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ يَعْنِي شَاذَانَ ‏ ‏الْمَعْنَى ‏","","",""],[14661,14661,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَرَدْنَا أَنْ نَبِيعَ دُورَنَا وَنَتَحَوَّلَ قَرِيبًا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَجْلِ الصَّلَاةِ قَالَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا فُلَانُ لِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏دِيَارَكُمْ فَإِنَّهَا تُكْتَبُ آثَارُكُمْ ‏","","",""],[14662,14662,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي كَرْبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رِجْلِ رَجُلٍ مِنَّا مِثْلَ الدِّرْهَمِ لَمْ يَغْسِلْهُ فَقَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَقِبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[14663,14663,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏دَبَّرَ ‏ ‏عَبْدًا لَهُ وَعَلَيْهِ دَيْنٌ ‏ ‏فَبَاعَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَيْنِ ‏ ‏مَوْلَاهُ ‏","","",""],[14664,14664,"","","‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ إِسْمَاعِيلَ الْقَاصُّ وَهُو أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ بِاللَّهِ الظَّنَّ فَإِنَّ قَوْمًا قَدْ أَرْدَاهُمْ سُوءُ ظَنِّهِمْ بِاللَّهِ عَزَّ وَجَلَّ ‏ { ‏وَذَلِكُمْ ظَنُّكُمْ الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُمْ مِنْ الْخَاسِرِينَ ‏}","","",""],[14665,14665,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَذَّبُ نَاسٌ مِنْ أَهْلِ التَّوْحِيدِ فِي النَّارِ حَتَّى يَكُونُوا حُمَمًا فِيهَا ثُمَّ تُدْرِكُهُمْ الرَّحْمَةُ فَيَخْرُجُونَ فَيُلْقَوْنَ عَلَى بَابِ الْجَنَّةِ فَيَرُشُّ عَلَيْهِمْ أَهْلُ الْجَنَّةِ الْمَاءَ فَيَنْبُتُونَ كَمَا يَنْبُتُ ‏ ‏الْغُثَاءُ ‏ ‏فِي ‏ ‏حِمَالَةِ ‏ ‏السَّيْلِ ثُمَّ يَدْخُلُونَ الْجَنَّةَ ‏","","",""],[14666,14666,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ أَيُّمَا مُؤْمِنٍ سَبَبْتُهُ أَوْ لَعَنْتُهُ أَوْ جَلَدْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَأَجْرًا ‏","","",""],[14667,14667,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَا الْمُوجِبَتَانِ قَالَ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ عَزَّ وَجَلَّ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ دَخَلَ النَّارَ ‏","","",""],[14668,14668,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَرَسَ غَرْسًا فَأَكَلَ مِنْهُ إِنْسَانٌ أَوْ طَيْرٌ أَوْ سَبُعٌ أَوْ دَابَّةٌ فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا الْمُوجِبَتَانِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[14669,14669,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَطْرُقَنَّ أَحَدُكُمْ أَهْلَهُ لَيْلًا ‏","","",""],[14670,14670,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَالْمُخَابَرَةِ ‏","","",""],[14671,14671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[14672,14672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُتِلَ أَبِي يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَتَرَكَ حَدِيقَتَيْنِ وَلِيَهُودِيٍّ عَلَيْهِ تَمْرٌ وَتَمْرُ الْيَهُودِيِّ يَسْتَوْعِبُ مَا فِي الْحَدِيقَتَيْنِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ لَكَ أَنْ تَأْخُذَ الْعَامَ بَعْضًا وَتُؤَخِّرَ بَعْضًا إِلَى قَابِلٍ فَأَبَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرَ ‏ ‏الْجِدَادُ ‏ ‏فَآذِنِّي قَالَ فَآذَنْتُهُ فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَجَعَلْنَا ‏ ‏نَجِدُّ ‏ ‏وَيُكَالُ لَهُ مِنْ أَسْفَلِ النَّخْلِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِالْبَرَكَةِ حَتَّى أَوْفَيْنَاهُ جَمِيعَ حَقِّهِ مِنْ أَصْغَرِ الْحَدِيقَتَيْنِ فِيمَا يَحْسِبُ ‏ ‏عَمَّارٌ ‏ ‏ثُمَّ أَتَيْنَاهُمْ بِرُطَبٍ وَمَاءٍ فَأَكَلُوا وَشَرِبُوا ثُمَّ قَالَ هَذَا مِنْ النَّعِيمِ الَّذِي تُسْأَلُونَ عَنْهُ ‏","","",""],[14673,14673,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏وَأَمَرَهُمْ ‏ ‏بِالسَّكِينَةِ ‏ ‏وَأَمَرَهُمْ أَنْ يَرْمُوا بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏وَأَوْضَعَ فِي ‏ ‏وَادِي مُحَسِّرٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏وَلَا أَدْرِي بِكَمْ رَمَى ‏ ‏الْجَمْرَةَ ‏","","",""],[14674,14674,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏أَجْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَائِشَةَ ‏ ‏أَهَدَيْتُمْ الْجَارِيَةَ إِلَى بَيْتِهَا قَالَتْ نَعَمْ قَالَ فَهَلَّا بَعَثْتُمْ مَعَهُمْ مَنْ ‏ ‏يُغَنِّيهِمْ يَقُولُ ‏ ‏أَتَيْنَاكُمْ أَتَيْنَاكُمْ ‏ ‏فَحَيُّونَا ‏ ‏نُحَيَّاكُمْ ‏ ‏فَإِنَّ ‏ ‏الْأَنْصَارَ ‏ ‏قَوْمٌ فِيهِمْ غَزَلٌ ‏","","",""],[14675,14675,"","","‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ إِسْمَاعِيلَ أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الصَّلَاةِ أَفْضَلُ قَالَ طُولُ ‏ ‏الْقُنُوتِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ وَأَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ وَأُرِيقَ دَمُهُ قَالَ يَا رَسُولَ اللَّهِ أَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ مَنْ هَجَرَ مَا كَرِهَ اللَّهُ عَزَّ وَجَلَّ قَالَ يَا رَسُولَ اللَّهِ فَأَيُّ الْمُسْلِمِينَ أَفْضَلُ قَالَ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ قَالَ يَا رَسُولَ اللَّهِ فَمَا الْمُوجِبَتَانِ قَالَ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ ‏ ‏شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏","","",""],[14676,14676,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا فَإِنْ لَمْ يَسْتَطِعْ أَنْ يَزْرَعَهَا وَعَجَزَ عَنْهَا فَلْيَمْنَحْهَا أَخَاهُ الْمُسْلِمَ وَلَا يُؤَاجِرْهَا ‏","","",""],[14677,14677,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ لِأَهْلِهَا ‏ ‏أَوْ مِيرَاثٌ لِأَهْلِهَا ‏","","",""],[14678,14678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلِي وَمَثَلُكُمْ كَمَثَلِ رَجُلٍ أَوْقَدَ نَارًا فَجَعَلَ الْفَرَاشُ ‏ ‏وَالْجَنَادِبُ ‏ ‏يَقَعْنَ فِيهَا وَهُوَ ‏ ‏يَذُبُّهُنَّ ‏ ‏عَنْهَا وَأَنَا آخِذٌ ‏ ‏بِحُجَزِكُمْ ‏ ‏عَنْ النَّارِ وَأَنْتُمْ ‏ ‏تَفَلَّتُونَ مِنْ يَدِي ‏","","",""],[14679,14679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَيُّ الْقُرْآنِ نَزَلَ أَوَّلَ قَالَ ‏ ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قَالَ فَإِنِّي أُنْبِئْتُ أَنَّ أَوَّلَ سُورَةٍ نَزَلَتْ ‏ ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏لَا أُحَدِّثُكَ إِلَّا كَمَا حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاوَرْتُ ‏ ‏فِي ‏ ‏حِرَاءٍ ‏ ‏فَلَمَّا قَضَيْتُ ‏ ‏جِوَارِي ‏ ‏نَزَلْتُ ‏ ‏فَاسْتَبْطَنْتُ ‏ ‏الْوَادِيَ ‏ ‏فَنُودِيتُ فَنَظَرْتُ بَيْنَ يَدَيَّ وَخَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي فَلَمْ أَرَ شَيْئًا فَنُودِيتُ أَيْضًا فَنَظَرْتُ بَيْنَ يَدَيَّ وَخَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي فَلَمْ أَرَ شَيْئًا فَنَظَرْتُ فَوْقِي فَإِذَا أَنَا بِهِ قَاعِدٌ عَلَى عَرْشٍ بَيْنَ السَّمَاءِ وَالْأَرْضِ فَجُئِثْتُ مِنْهُ فَأَتَيْتُ مَنْزِلَ ‏ ‏خَدِيجَةَ ‏ ‏فَقُلْتُ ‏ ‏دَثِّرُونِي ‏ ‏وَصُبُّوا عَلَيَّ مَاءً بَارِدًا قَالَ فَنَزَلَتْ عَلَيَّ ‏ { ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قُمْ فَأَنْذِرْ وَرَبَّكَ فَكَبِّرْ ‏}","","",""],[14680,14680,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ الصَّاغَانِيُّ مُحَمَّدُ بْنُ مُيَسَّرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَالْمُخَابَرَةِ ‏ ‏وَأَنْ يُبَاعَ الثَّمَرُ حَتَّى ‏ ‏يُطْعَمَ ‏ ‏إِلَّا بِدَنَانِيرَ أَوْ دَرَاهِمَ إِلَّا ‏ ‏الْعَرَايَا ‏","","",""],[14681,14681,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ الصَّنْعَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِيعُهُ حَتَّى يَسْتَوْفِيَهُ ‏","","",""],[14682,14682,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَايَعَهُ ‏ ‏عَلَى الْإِسْلَامِ فَجَاءَ مِنْ الْغَدِ ‏ ‏مَحْمُومًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَقِلْنِي ‏ ‏فَأَبَى فَجَاءَهُ ثَلَاثَةَ أَيَّامٍ مُتَوَالِيَةٍ كُلُّ ذَلِكَ يَقُولُ يَا رَسُولَ اللَّهِ ‏ ‏أَقِلْنِي ‏ ‏فَيَأْبَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا وَلَّى قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْمَدِينَةَ ‏ ‏كَالْكِيرِ ‏ ‏تَنْفِي ‏ ‏خَبَثَهَا ‏ ‏وَتَنْصَعُ ‏ ‏طَيِّبَهَا ‏","","",""],[14683,14683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[14684,14684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ فَإِنْ شَاءَ طَعِمَ وَإِنْ شَاءَ تَرَكَ ‏","","",""],[14685,14685,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيعَنَّ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏دَعُوا النَّاسَ يَرْزُقُ اللَّهُ بَعْضَهُمْ مِنْ بَعْضٍ ‏","","",""],[14686,14686,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ يَعْنِي ابْنَ سَوَّارٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ مَسْجِدَنَا هَذَا بَعْدَ عَامِنَا هَذَا مُشْرِكٌ إِلَّا أَهْلُ ‏ ‏الْعَهْدِ ‏ ‏وَخَدَمُهُمْ ‏","","",""],[14687,14687,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏اشْتَرَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي بَعِيرًا عَلَى أَنْ يُفْقِرَنِي ظَهْرَهُ سَفَرَهُ ‏ ‏أَوْ سَفَرِي ‏ ‏ذَلِكَ ثُمَّ أَعْطَانِي الْبَعِيرَ وَالثَّمَنَ ‏","","",""],[14688,14688,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ ‏ ‏قَالَ يَرَوْنَ أَنَّهَا غَزْوَةُ ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏فَكَسَعَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏الْأَنْصَارِيُّ ‏ ‏يَا ‏ ‏لَلْأَنْصَارِ ‏ ‏وَقَالَ ‏ ‏الْمُهَاجِرِيُّ ‏ ‏يَا ‏ ‏لَلْمُهَاجِرِينَ ‏ ‏فَسَمِعَ ذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا بَالُ دَعْوَى الْجَاهِلِيَّةِ فَقِيلَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏كَسَعَ ‏ ‏رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهَا فَإِنَّهَا مُنْتِنَةٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏وَكَانَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏حِينَ قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏أَقَلَّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ثُمَّ إِنَّ ‏ ‏الْمُهَاجِرِينَ ‏ ‏كَثُرُوا فَبَلَغَ ذَلِكَ ‏ ‏عَبْدَ اللَّهِ بْنَ أُبَيٍّ ‏ ‏فَقَالَ فَعَلُوهَا وَاللَّهِ لَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ فَسَمِعَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ دَعْنِي أَضْرِبُ عُنُقَ هَذَا الْمُنَافِقِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُمَرُ ‏ ‏دَعْهُ لَا يَتَحَدَّثُ النَّاسُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏يَقْتُلُ أَصْحَابَهُ ‏","","",""],[14689,14689,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِلَعْقِ الْأَصَابِعِ ‏ ‏وَالصَّحْفَةِ ‏ ‏وَقَالَ لَا يَدْرِي أَحَدُكُمْ فِي أَيِّ ذَلِكَ الْبَرَكَةَ ‏","","",""],[14690,14690,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَدْ أَخَافَ مَا بَيْنَ جَنْبَيَّ ‏","","",""],[14691,14691,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي كَرْبٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَاقِيبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[14692,14692,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ بْنُ سَعْدٍ الْأَنْصَارِيُّ ‏ ‏مَوْلَى ‏ ‏بَنِي خَطْمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَكُفَّ أَحَدُكُمْ يَدَهُ عَنْ الْحَصَى خَيْرٌ لَهُ مِنْ مِائَةِ نَاقَةٍ كُلُّهَا سُودُ الْحَدَقَةِ فَإِنْ غَلَبَ أَحَدَكُمْ الشَّيْطَانُ فَلْيَمْسَحْ مَسْحَةً وَاحِدَةً ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يُمْسِكَ أَحَدُكُمْ يَدَهُ عَنْ الْحَصَى فَذَكَرَ مِثْلَهُ ‏","","",""],[14693,14693,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا أَعْتَقَ عَبْدًا لَهُ لَيْسَ لَهُ غَيْرُهُ فَرَدَّهُ عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَابْتَاعَهُ مِنْهُ ‏ ‏نُعَيْمُ بْنُ النَّحَّامِ ‏","","",""],[14694,14694,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى مَسْجِدَ ‏ ‏يَعْنِي الْأَحْزَابَ ‏ ‏فَوَضَعَ رِدَاءَهُ وَقَامَ وَرَفَعَ يَدَيْهِ ‏ ‏مَدًّا ‏ ‏يَدْعُو عَلَيْهِمْ وَلَمْ يُصَلِّ قَالَ ثُمَّ جَاءَ وَدَعَا عَلَيْهِمْ وَصَلَّى ‏","","",""],[14695,14695,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِي الْعُمْرَى أَنَّهَا لِمَنْ وُهِبَتْ لَهُ ‏","","",""],[14696,14696,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الطَّوَافِ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَقَالَ كُنَّا نَطُوفُ فَنَمْسَحُ الرُّكْنَ الْفَاتِحَةَ وَالْخَاتِمَةَ وَلَمْ نَكُنْ نَطُوفُ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَلَا بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَطْلُعُ الشَّمْسُ عَلَى ‏ ‏قَرْنَيْ الشَّيْطَانِ ‏","","",""],[14697,14697,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ ‏ ‏الْمَدِينَةِ ‏ ‏كَالْكِيرِ ‏ ‏وَحَرَّمَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا أُحَرِّمُ ‏ ‏الْمَدِينَةَ ‏ ‏وَهِيَ ‏ ‏كَمَكَّةَ ‏ ‏حَرَامٌ مَا بَيْنَ حَرَّتَيْهَا وَحِمَاهَا كُلُّهَا لَا يُقْطَعُ مِنْهَا شَجَرَةٌ إِلَّا أَنْ يَعْلِفَ رَجُلٌ مِنْهَا وَلَا يَقْرَبُهَا إِنْ شَاءَ اللَّهُ الطَّاعُونُ وَلَا ‏ ‏الدَّجَّالُ ‏ ‏وَالْمَلَائِكَةُ يَحْرُسُونَهَا عَلَى ‏ ‏أَنْقَابِهَا ‏ ‏وَأَبْوَابِهَا قَالَ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَلَا يَحِلُّ لِأَحَدٍ يَحْمِلُ فِيهَا سِلَاحًا لِقِتَالٍ ‏","","",""],[14698,14698,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرُّقْيَةِ ‏ ‏فَقَالَ أَخْبَرَنِي ‏ ‏خَالِي ‏ ‏أَحَدُ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرْقِي مِنْ الْعَقْرَبِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ بِشَيْءٍ فَلْيَفْعَلْ ‏","","",""],[14699,14699,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ حَزْمٍ ‏ ‏دُعِيَ لِامْرَأَةٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏لَدَغَتْهَا حَيَّةٌ لَيَرْقِيَهَا فَأَبَى فَأُخْبِرَ بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَاهُ فَقَالَ ‏ ‏عَمْرٌو ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّكَ تَزْجُرُ عَنْ الرُّقَى فَقَالَ اقْرَأْهَا عَلَيَّ فَقَرَأَهَا عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا بَأْسَ إِنَّمَا هِيَ مَوَاثِيقُ فَارْقِ بِهَا ‏","","",""],[14700,14700,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُدْخِلُ أَحَدَكُمْ الْجَنَّةَ عَمَلُهُ وَلَا ‏ ‏يُنَجِّيهِ عَمَلُهُ مِنْ النَّارِ قِيلَ وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا بِرَحْمَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[14701,14701,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَسَقَطَتْ لُقْمَتُهُ ‏ ‏فَلْيُمِطْ ‏ ‏مَا ‏ ‏أَرَابَهُ ‏ ‏مِنْهَا ثُمَّ لِيَطْعَمْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ وَلَا يَمْسَحْ أَحَدُكُمْ يَدَهُ بِالْمِنْدِيلِ حَتَّى يَلْعَقَ يَدَهُ فَإِنَّ الرَّجُلَ لَا يَدْرِي فِي أَيِّ طَعَامِهِ يُبَارَكُ لَهُ فَإِنَّ الشَّيْطَانَ ‏ ‏يَرْصُدُ ‏ ‏ابْنَ ‏ ‏آدَمَ ‏ ‏عِنْدَ كُلِّ شَيْءٍ حَتَّى عِنْدَ طَعَامِهِ ‏","","",""],[14702,14702,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اجْتَنِبُوا الْكَبَائِرَ وَسَدِّدُوا وَأَبْشِرُوا ‏","","",""],[14703,14703,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْخَرْصِ ‏ ‏وَقَالَ أَرَأَيْتُمْ إِنْ هَلَكَ التَّمْرُ أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ مَالَ أَخِيهِ بِالْبَاطِلِ ‏","","",""],[14704,14704,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَبْدُ مَعَ مَنْ أَحَبَّ ‏","","",""],[14705,14705,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[14706,14706,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنَيْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى الْمُحَدَّثُ الْمُحَدِّثَ يَتَلَفَّتُ فَهِيَ أَمَانَةٌ ‏","","",""],[14707,14707,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏ثَلَاثَةَ أَطْوَافٍ مِنْ الْحَجَرِ إِلَى الْحَجَرِ وَصَلَّى رَكْعَتَيْنِ ثُمَّ عَادَ إِلَى الْحَجَرِ ثُمَّ ذَهَبَ إِلَى ‏ ‏زَمْزَمَ ‏ ‏فَشَرِبَ مِنْهَا وَصَبَّ عَلَى رَأْسِهِ ثُمَّ رَجَعَ ‏ ‏فَاسْتَلَمَ ‏ ‏الرُّكْنَ ثُمَّ رَجَعَ إِلَى ‏ ‏الصَّفَا ‏ ‏فَقَالَ ابْدَءُوا بِمَا بَدَأَ اللَّهُ عَزَّ وَجَلَّ بِهِ ‏","","",""],[14708,14708,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّي ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ ‏ ‏مُفْرَدًا ‏ ‏فَأَقْبَلَتْ ‏ ‏عَائِشَةُ ‏ ‏مُهِلَّةً ‏ ‏بِعُمْرَةٍ حَتَّى إِذَا كَانَتْ ‏ ‏بِسَرِفَ ‏ ‏عَرَكَتْ ‏ ‏حَتَّى إِذَا قَدِمْنَا طُفْنَا ‏ ‏بِالْكَعْبَةِ ‏ ‏وَالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَأَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَحِلَّ ‏ ‏مِنَّا مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏قَالَ فَقُلْنَا حِلُّ مَاذَا قَالَ الْحِلُّ كُلُّهُ ‏ ‏فَوَاقَعْنَا ‏ ‏النِّسَاءَ وَتَطَيَّبْنَا بِالطِّيبِ وَلَيْسَ بَيْنَنَا وَبَيْنَ ‏ ‏عَرَفَةَ ‏ ‏إِلَّا أَرْبَعُ لَيَالٍ ثُمَّ ‏ ‏أَهْلَلْنَا ‏ ‏يَوْمَ التَّرْوِيَةِ ‏ ‏ثُمَّ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَوَجَدَهَا تَبْكِي قَالَ مَا شَأْنُكِ قَالَتْ شَأْنِي أَنِّي حِضْتُ وَقَدْ حَلَّ النَّاسُ وَلَمْ ‏ ‏أَحْلِلْ ‏ ‏وَلَمْ أَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَالنَّاسُ يَذْهَبُونَ إِلَى الْحَجِّ الْآنَ قَالَ فَإِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَزَّ وَجَلَّ عَلَى بَنَاتِ ‏ ‏آدَمَ ‏ ‏فَاغْتَسِلِي ثُمَّ ‏ ‏أَهِلِّي ‏ ‏بِالْحَجِّ فَفَعَلَتْ وَوَقَفَتْ الْمَوَاقِفَ كُلَّهَا حَتَّى إِذَا طَهُرَتْ طَافَتْ ‏ ‏بِالْكَعْبَةِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ قَالَ قَدْ ‏ ‏حَلَلْتِ ‏ ‏مِنْ حَجِّكِ وَعُمْرَتِكِ جَمِيعًا فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ فِي نَفْسِي أَنِّي لَمْ أَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏حَتَّى حَجَجْتُ قَالَ فَاذْهَبْ بِهَا يَا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ ‏ ‏فَأَعْمِرْهَا مِنْ ‏ ‏التَّنْعِيمِ ‏ ‏وَذَلِك لَيْلَةَ ‏ ‏الْحَصْبَةِ ‏","","",""],[14709,14709,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ مَثَلُ السُّنْبُلَةِ ‏ ‏مَرَّةً تَسْتَقِيمُ وَمَرَّةً تَمِيلُ وَتَعْتَدِلُ وَمَثَلُ الْكَافِرِ مَثَلُ الْأَرْزَةِ مُسْتَقِيمَةً لَا يَشْعُرُ بِهَا حَتَّى تَخِرَّ ‏","","",""],[14710,14710,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَطَاءً ‏ ‏أَنَّ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏بَاعَ ثَمَرَ أَرْضٍ لَهُ ثَلَاثَ سِنِينَ فَسَمِعَ بِذَلِكَ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏فَخَرَجَ إِلَى الْمَسْجِدِ فِي نَاسٍ فَقَالَ فِي الْمَسْجِدِ ‏ ‏مَنَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَبِيعَ الثَّمَرَةَ حَتَّى تَطِيبَ ‏","","",""],[14711,14711,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِامْرَأَةٍ قَدْ سَرَقَتْ فَعَاذَتْ ‏ ‏بِرَبِيبِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏لَوْ كَانَتْ ‏ ‏فَاطِمَةَ ‏ ‏لَقَطَعْتُ يَدَهَا فَقَطَعَهَا ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏وَكَانَ ‏ ‏رَبِيبُ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَمَةَ بْنَ أَبِي سَلَمَةَ ‏ ‏وَعُمَرَ بْنَ أَبِي سَلَمَةَ ‏ ‏فَعَاذَتْ بِأَحَدِهِمَا ‏","","",""],[14712,14712,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ ‏ ‏يُبَاشِرَ ‏ ‏الرَّجُلُ الرَّجُلَ فِي ثَوْبٍ وَاحِدٍ وَالْمَرْأَةُ الْمَرْأَةَ فِي ثَوْبٍ وَاحِدٍ وَقَالَ إِذَا أَعْجَبَتْ أَحَدَكُمْ الْمَرْأَةُ ‏ ‏فَلْيَقَعْ ‏ ‏عَلَى أَهْلِهِ فَإِنَّ ذَلِكَ يَرُدُّ مِنْ نَفْسِهِ ‏","","",""],[14713,14713,"","","‏ ‏و قَالَ ‏ ‏جَابِرٌ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الطُّرُوقِ ‏ ‏إِذَا جِئْنَا مِنْ السَّفَرِ ‏","","",""],[14714,14714,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ جَعْفَرٍ الْمَدَائِنِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وُثِيَتْ ‏ ‏رِجْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلْنَا عَلَيْهِ فَخَرَجَ إِلَيْنَا ‏ ‏أَوْ وَجَدْنَاهُ فِي حُجْرَتِهِ جَالِسًا بَيْنَ يَدَيْ ‏ ‏غُرْفَةٍ ‏ ‏فَصَلَّى جَالِسًا وَقُمْنَا خَلْفَهُ فَصَلَّيْنَا فَلَمَّا قَضَى الصَّلَاةَ قَالَ ‏ ‏إِذَا صَلَّيْتُ جَالِسًا فَصَلُّوا جُلُوسًا وَإِذَا صَلَّيْتُ قَائِمًا فَصَلُّوا قِيَامًا وَلَا تَقُومُوا كَمَا تَقُومُ ‏ ‏فَارِسُ ‏ ‏لِجَبَابِرَتِهَا ‏ ‏أَوْ لِمُلُوكِهَا ‏","","",""],[14715,14715,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْأَرْضِ الْبَيْضَاءِ السَّنَتَيْنِ وَالثَّلَاثَةَ ‏","","",""],[14716,14716,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَيَحْيَى بْنُ آدَمَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَمَنْ لَمْ يَجِدْ ‏ ‏إِزَارًا ‏ ‏فَلْيَلْبَسْ سَرَاوِيلَ ‏","","",""],[14717,14717,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏انْتَهَبَ ‏ ‏نُهْبَةً ‏ ‏فَلَيْسَ مِنَّا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَاه ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏أَيْضًا ‏","","",""],[14718,14718,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرِ حَتَّى يَطِيبَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو النَّضْرِ ‏","","",""],[14719,14719,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَغْلِقُوا الْأَبْوَابَ ‏ ‏وَأَوْكِئُوا ‏ ‏الْأَسْقِيَةَ ‏ ‏وَخَمِّرُوا ‏ ‏الْآنِيَةَ وَأَطْفِئُوا ‏ ‏السُّرُجَ ‏ ‏فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ غَلَقًا وَلَا يَحُلُّ ‏ ‏وِكَاءً ‏ ‏وَلَا يَكْشِفُ إِنَاءً وَإِنَّ ‏ ‏الْفُوَيْسِقَةَ ‏ ‏تُضْرِمُ ‏ ‏عَلَى أَهْلِ الْبَيْتِ وَلَا تُرْسِلُوا ‏ ‏فَوَاشِيَكُمْ ‏ ‏وَصِبْيَانَكُمْ إِذَا غَابَتْ الشَّمْسُ حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ فَإِنَّ الشَّيَاطِينَ تُبْعَثُ إِذَا غَابَتْ الشَّمْسُ حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ ‏","","",""],[14720,14720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَلَمَةَ بْنِ أَبِي يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَابِرٌ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَبِي تَرَكَ دَيْنًا ‏ ‏لِيَهُودَ ‏ ‏فَقَالَ ‏ ‏سَآتِيكَ يَوْمَ السَّبْتِ إِنْ شَاءَ اللَّهُ وَذَلِكَ فِي زَمَنِ التَّمْرِ مَعَ ‏ ‏اسْتِجْدَادِ ‏ ‏النَّخْلِ فَلَمَّا كَانَ صَبِيحَةُ يَوْمِ السَّبْتِ جَاءَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا دَخَلَ عَلَيَّ فِي مَاءٍ لِي ‏ ‏دَنَا ‏ ‏إِلَى ‏ ‏الرَّبِيعِ ‏ ‏فَتَوَضَّأَ ثُمَّ قَامَ إِلَى الْمَسْجِدِ فَصَلَّى رَكْعَتَيْنِ ثُمَّ ‏ ‏دَنَوْتُ ‏ ‏بِهِ إِلَى خَيْمَةٍ لِي فَبَسَطْتُ لَهُ ‏ ‏بِجَادًا ‏ ‏مِنْ شَعْرٍ وَطَرَحْتُ ‏ ‏خُدَيَّةً مِنْ ‏ ‏قَتَبٍ ‏ ‏مِنْ شَعْرٍ حَشْوُهَا مِنْ لِيفٍ فَاتَّكَأَ عَلَيْهَا فَلَمْ أَلْبَثْ إِلَّا قَلِيلًا حَتَّى طَلَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَكَأَنَّهُ نَظَرَ إِلَى مَا عَمِلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ وَصَلَّى ‏ ‏رَكْعَتَيْنِ فَلَمْ أَلْبَثْ إِلَّا قَلِيلًا حَتَّى جَاءَ ‏ ‏عُمَرُ ‏ ‏فَتَوَضَّأَ وَصَلَّى رَكْعَتَيْنِ كَأَنَّهُ نَظَرَ إِلَى صَاحِبَيْهِ فَدَخَلَا فَجَلَسَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عِنْدَ رَأْسِهِ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عِنْدَ رِجْلَيْهِ ‏","","",""],[14721,14721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏وَعَتَّابٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ سَلَمَةَ بْنِ أَبِي يَزِيدَ الْمَدِينِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏اسْتُشْهِدَ أَبِي ‏ ‏بِأُحُدٍ ‏ ‏فَأَرْسَلْنَنِي أَخَوَاتِي إِلَيْهِ بِنَاضِحٍ لَهُنَّ فَقُلْنَ اذْهَبْ فَاحْتَمِلْ أَبَاكَ عَلَى هَذَا الْجَمَلِ فَادْفِنْهُ فِي مَقْبَرَةِ ‏ ‏بَنِي سَلِمَةَ ‏ ‏قَالَ فَجِئْتُهُ وَأَعْوَانٌ لِي فَبَلَغَ ذَلِكَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَالِسٌ ‏ ‏بِأُحُدٍ ‏ ‏فَدَعَانِي وَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا يُدْفَنُ إِلَّا مَعَ إِخْوَتِهِ فَدُفِنَ مَعَ أَصْحَابِهِ ‏ ‏بِأُحُدٍ ‏","","",""],[14722,14722,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْعَبَّاسُ ‏ ‏آخِذًا بِيَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوَاثِقُنَا ‏ ‏فَلَمَّا فَرَغْنَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذْتُ وَأَعْطَيْتُ قَالَ فَسَأَلْتُ ‏ ‏جَابِرًا ‏ ‏يَوْمَئِذٍ كَيْفَ ‏ ‏بَايَعْتُمْ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعَلَى الْمَوْتِ قَالَ لَا وَلَكِنْ ‏ ‏بَايَعْنَاهُ ‏ ‏عَلَى أَنْ لَا ‏ ‏نَفِرَّ ‏ ‏قُلْتُ لَهُ أَفَرَأَيْتَ يَوْمَ الشَّجَرَةِ قَالَ كُنْتُ آخِذًا بِيَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏حَتَّى ‏ ‏بَايَعْنَاهُ ‏ ‏قُلْتُ كَمْ كُنْتُمْ قَالَ كُنَّا أَرْبَعَ عَشَرَ مِائَةً ‏ ‏فَبَايَعْنَاهُ ‏ ‏كُلُّنَا إِلَّا ‏ ‏الْجَدَّ بْنَ قَيْسٍ ‏ ‏اخْتَبَأَ تَحْتَ بَطْنِ بَعِيرٍ ‏ ‏وَنَحَرْنَا ‏ ‏يَوْمَئِذٍ سَبْعِينَ مِنْ ‏ ‏الْبُدْنِ ‏ ‏لِكُلِّ سَبْعَةٍ ‏ ‏جَزُورٌ ‏","","",""],[14723,14723,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ السَّلَمِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَبْصُقْ أَمَامَهُ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمَيْهِ ‏","","",""],[14724,14724,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ فِي ‏ ‏الْكَعْبَةِ ‏ ‏صُوَرٌ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَنْ يَمْحُوَهَا فَبَلَّ ‏ ‏عُمَرُ ‏ ‏ثَوْبًا وَمَحَاهَا بِهِ فَدَخَلَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا فِيهَا مِنْهَا شَيْءٌ ‏","","",""],[14725,14725,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ يَدْخُلَ النَّارَ رَجُلٌ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏","","",""],[14726,14726,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ فَدَعَا بِهَا ‏ ‏وَإِنِّي ‏ ‏اسْتَخْبَأْتُ دَعْوَتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[14727,14727,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الصِّيَامُ جُنَّةٌ يَسْتَجِنُّ بِهَا الْعَبْدُ مِنْ النَّارِ هُوَ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[14728,14728,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ سُلَيْمَانَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَطَالَ أَحَدُكُمْ الْغَيْبَةَ فَلَا يَطْرُقَنَّ أَهْلَهُ لَيْلًا ‏","","",""],[14729,14729,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ سَلَمَةَ بْنِ أَبِي يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَابِرٌ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَمَدْتُ إِلَى عَنْزٍ لِأَذْبَحَهَا ‏ ‏فَثَغَتْ ‏ ‏فَسَمِعَ ‏ ‏ثَغَوْتهَا ‏ ‏فَقَالَ يَا ‏ ‏جَابِرُ ‏ ‏لَا تَقْطَعْ دَرًّا وَلَا نَسْلًا ‏ ‏فَقُلْتُ ‏ ‏يَا نَبِيَّ اللَّهِ إِنَّمَا هِيَ ‏ ‏عَتُودَةٌ ‏ ‏عَلَفْتُهَا الْبَلَحَ ‏ ‏وَالرُّطَبَ ‏ ‏حَتَّى سَمِنَتْ ‏","","",""],[14730,14730,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِأَبِي شُعَيْبٍ ‏ ‏غُلَامٌ لَحَّامٌ فَلَمَّا رَأَى مَا بِرَسُولِ اللَّهِ مِنْ الْجَهْدِ أَمَرَ غُلَامَهُ أَنْ يَجْعَلَ لَهُ طَعَامًا يَكْفِي خَمْسَةً فَأَرْسَلَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ائْتِنَا خَامِسَ خَمْسَةٍ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّبَعَهُ رَجُلٌ فَلَمَّا انْتَهَيَا إِلَى بَابِهِ قَالَ ‏ ‏إِنَّكَ أَرْسَلْتَ إِلَيَّ أَنْ آتِيَكَ خَامِسَ خَمْسَةٍ وَإِنَّ هَذَا قَدْ اتَّبَعَنَا فَإِنْ أَذِنْتَ لَهُ دَخَلَ وَإِلَّا رَجَعَ قَالَ فَإِنِّي قَدْ أَذِنْتُ لَهُ يَا رَسُولَ اللَّهِ فَدَخَلَ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[14731,14731,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏الْخَطَّابُ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَقَرَّتْ النُّطْفَةُ فِي الرَّحِمِ أَرْبَعِينَ يَوْمًا ‏ ‏أَوْ أَرْبَعِينَ لَيْلَةً ‏ ‏بَعَثَ إِلَيْهَا مَلَكًا فَيَقُولُ يَا رَبِّ مَا رِزْقُهُ فَيُقَالُ لَهُ فَيَقُولُ يَا رَبِّ مَا أَجَلُهُ فَيُقَالُ لَهُ فَيَقُولُ يَا رَبِّ ذَكَرٌ أَوْ أُنْثَى فَيُعْلَمُ فَيَقُولُ يَا رَبِّ شَقِيٌّ أَوْ سَعِيدٌ فَيُعْلَمُ ‏","","",""],[14732,14732,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[14733,14733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏وَصَلَاةٌ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏أَفْضَلُ مِنْ مِائَةِ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ ‏","","",""],[14734,14734,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏مَرَّ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْغَائِطِ ‏ ‏فَدَعَوْنَاهُ إِلَى عَجْوَةٍ بَيْنَ أَيْدِينَا عَلَى ‏ ‏تُرْسٍ ‏ ‏فَأَكَلَ مِنْهَا وَلَمْ يَكُنْ تَوَضَّأَ قَبْلَ أَنْ يَأْكُلَ مِنْهَا ‏","","",""],[14735,14735,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَقْرَأُ الْقُرْآنَ وَفِينَا ‏ ‏الْعَجَمِيُّ وَالْأَعْرَابِيُّ قَالَ فَاسْتَمَعَ فَقَالَ اقْرَءُوا فَكُلٌّ حَسَنٌ ‏ ‏وَسَيَأْتِي قَوْمٌ يُقِيمُونَهُ كَمَا يُقَامُ ‏ ‏الْقِدْحُ ‏ ‏يَتَعَجَّلُونَهُ وَلَا يَتَأَجَّلُونَهُ ‏","","",""],[14736,14736,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ يَعْنِي ابْنَ صَبِيحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَانَا عَنْ أَكْلِ الْكُرَّاثِ وَالْبَصَلِ ‏ ‏قَالَ ‏ ‏الرَّبِيعُ ‏ ‏فَسَأَلْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ ذَلِكَ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[14737,14737,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏مِنْ الْحَجَرِ حَتَّى عَادَ إِلَيْهِ ‏","","",""],[14738,14738,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏قَدْ أَخَذْتُ جَمَلَكَ بِأَرْبَعَةِ الدَّنَانِيرِ وَلَكَ ظَهْرُهُ إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[14739,14739,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَّ خَطًّا هَكَذَا أَمَامَهُ فَقَالَ هَذَا سَبِيلُ اللَّهِ عَزَّ وَجَلَّ وَخَطَّيْنِ عَنْ يَمِينِهِ وَخَطَّيْنِ عَنْ شِمَالِهِ قَالَ هَذِهِ سَبِيلُ الشَّيْطَانِ ثُمَّ وَضَعَ يَدَهُ فِي الْخَطِّ الْأَسْوَدِ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ ‏}","","",""],[14740,14740,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَدْخُلَ عَلَى ‏ ‏الْمُغِيبَاتِ ‏","","",""],[14741,14741,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ شَرِيكًا فِي ‏ ‏رَبْعَةٍ ‏ ‏أَوْ نَخْلٍ فَلَيْسَ لَهُ أَنْ يَبِيعَ حَتَّى يُؤْذِنَ شَرِيكَهُ فَإِنْ رَضِيَ أَخَذَ وَإِنْ كَرِهَ تَرَكَ ‏","","",""],[14742,14742,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَمُطِرْنَا فَقَالَ مَنْ شَاءَ مِنْكُمْ فَلْيُصَلِّ فِي ‏ ‏رَحْلِهِ ‏","","",""],[14743,14743,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى الْمُشْرِكِينَ لِيُقَاتِلَهُمْ وَقَالَ ‏ ‏لِي ‏ ‏أَبِي عَبْدُ اللَّهِ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏لَا عَلَيْكَ أَنْ تَكُونَ فِي ‏ ‏نَظَّارِي ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى تَعْلَمَ إِلَى مَا يَصِيرُ أَمْرُنَا فَإِنِّي ‏ ‏وَاللَّهِ لَوْلَا أَنِّي أَتْرُكُ بَنَاتٍ لِي بَعْدِي لَأَحْبَبْتُ أَنْ تُقْتَلَ بَيْنَ يَدَيَّ قَالَ فَبَيْنَمَا أَنَا فِي ‏ ‏النَّظَّارِينَ ‏ ‏إِذْ جَاءَتْ عَمَّتِي بِأَبِي وَخَالِي عَادِلَتَهُمَا عَلَى ‏ ‏نَاضِحٍ ‏ ‏فَدَخَلَتْ بِهِمَا ‏ ‏الْمَدِينَةَ ‏ ‏لِتَدْفِنَهُمَا فِي مَقَابِرِنَا إِذْ لَحِقَ رَجُلٌ يُنَادِي أَلَا إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُكُمْ أَنْ تَرْجِعُوا بِالْقَتْلَى فَتَدْفِنُوهَا فِي ‏ ‏مَصَارِعِهَا ‏ ‏حَيْثُ قُتِلَتْ فَرَجَعْنَا بِهِمَا فَدَفَنَّاهُمَا حَيْثُ قُتِلَا فَبَيْنَمَا أَنَا فِي خِلَافَةِ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏إِذْ جَاءَنِي رَجُلٌ فَقَالَ يَا ‏ ‏جَابِرُ بْنَ عَبْدِ اللَّهِ ‏ ‏وَاللَّهِ لَقَدْ أَثَارَ أَبَاكَ عَمَلُ ‏ ‏مُعَاوِيَةَ ‏ ‏فَبَدَا فَخَرَجَ طَائِفَةٌ مِنْهُ فَأَتَيْتُهُ فَوَجَدْتُهُ عَلَى النَّحْوِ الَّذِي دَفَنْتُهُ لَمْ يَتَغَيَّرْ إِلَّا مَا لَمْ يَدَعْ الْقَتْلُ ‏ ‏أَوْ الْقَتِيلُ ‏ ‏فَوَارَيْتُهُ ‏ ‏قَالَ وَتَرَكَ أَبِي عَلَيْهِ دَيْنًا مِنْ التَّمْرِ فَاشْتَدَّ عَلَيَّ بَعْضُ ‏ ‏غُرَمَائِهِ ‏ ‏فِي التَّقَاضِي فَأَتَيْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا نَبِيَّ اللَّهِ إِنَّ أَبِي أُصِيبَ يَوْمَ كَذَا وَكَذَا وَتَرَكَ عَلَيَّ دَيْنًا مِنْ التَّمْرِ وَاشْتَدَّ عَلَيَّ بَعْضُ ‏ ‏غُرَمَائِهِ ‏ ‏فِي التَّقَاضِي فَأُحِبُّ أَنْ تُعِينَنِي عَلَيْهِ لَعَلَّه أَنْ ‏ ‏يُنَظِّرَنِي ‏ ‏طَائِفَةً مِنْ تَمْرِهِ إِلَى هَذَا ‏ ‏الصِّرَامِ ‏ ‏الْمُقْبِلِ فَقَالَ نَعَمْ ‏ ‏آتِيكَ إِنْ شَاءَ اللَّهُ قَرِيبًا مِنْ وَسَطِ النَّهَارِ وَجَاءَ مَعَهُ ‏ ‏حَوَارِيُّهُ ‏ ‏ثُمَّ اسْتَأْذَنَ وَدَخَلَ فَقُلْتُ لِامْرَأَتِي إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنِي الْيَوْمَ وَسَطَ النَّهَارِ فَلَا أَرَيْتُكِ وَلَا تُؤْذِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي بِشَيْءٍ وَلَا تُكَلِّمِيهِ فَدَخَلَ فَفَرَشَتْ لَهُ فِرَاشًا وَوِسَادَةً فَوَضَعَ رَأْسَهُ فَنَامَ قَالَ وَقُلْتُ ‏ ‏لِمَوْلًى ‏ ‏لِيَ اذْبَحْ هَذِهِ ‏ ‏الْعَنَاقَ ‏ ‏وَهِيَ ‏ ‏دَاجِنٌ ‏ ‏سَمِينَةٌ ‏ ‏وَالْوَحَا ‏ ‏وَالْعَجَلَ افْرُغْ مِنْهَا قَبْلَ أَنْ يَسْتَيْقِظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَكَ فَلَمْ نَزَلْ فِيهَا حَتَّى فَرَغْنَا مِنْهَا وَهُوَ نَائِمٌ فَقُلْتُ لَهُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ يَدْعُو بِالطَّهُورِ وَإِنِّي أَخَافُ إِذَا فَرَغَ أَنْ يَقُومَ فَلَا يَفْرَغَنَّ مِنْ وُضُوئِهِ حَتَّى تَضَعَ ‏ ‏الْعَنَاقَ ‏ ‏بَيْنَ يَدَيْهِ فَلَمَّا قَامَ قَالَ يَا ‏ ‏جَابِرُ ‏ ‏ائْتِنِي بِطَهُورٍ فَلَمْ يَفْرُغْ مِنْ طُهُورِهِ حَتَّى وَضَعْتُ ‏ ‏الْعَنَاقَ ‏ ‏عِنْدَهُ فَنَظَرَ إِلَيَّ فَقَالَ كَأَنَّكَ قَدْ عَلِمْتَ حُبَّنَا لِلَّحْمِ ادْعُ لِي ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ ثُمَّ دَعَا ‏ ‏حَوَارِيَّيْهِ ‏ ‏اللَّذَيْنِ مَعَهُ فَدَخَلُوا فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ وَقَالَ ‏ ‏بِسْمِ اللَّهِ كُلُوا فَأَكَلُوا حَتَّى شَبِعُوا وَفَضَلَ لَحْمٌ مِنْهَا كَثِيرٌ قَالَ وَاللَّهِ إِنَّ مَجْلِسَ ‏ ‏بَنِي سَلِمَةَ ‏ ‏لَيَنْظُرُونَ إِلَيْهِ وَهُوَ أَحَبُّ إِلَيْهِمْ مِنْ أَعْيُنِهِمْ مَا يَقْرُبُهُ رَجُلٌ مِنْهُمْ مَخَافَةَ أَنْ يُؤْذُوهُ فَلَمَّا فَرَغَ قَامَ وَقَامَ أَصْحَابُهُ فَخَرَجُوا بَيْنَ يَدَيْهِ وَكَانَ يَقُولُ خَلُّوا ظَهْرِي لِلْمَلَائِكَةِ وَاتَّبَعْتُهُمْ حَتَّى بَلَغُوا ‏ ‏أُسْكُفَّةَ ‏ ‏الْبَابِ قَالَ وَأَخْرَجَتْ امْرَأَتِي صَدْرَهَا وَكَانَتْ مُسْتَتِرَةً ‏ ‏بِسَقِيفٍ ‏ ‏فِي الْبَيْتِ قَالَتْ يَا رَسُولَ اللَّهِ صَلِّ عَلَيَّ وَعَلَى زَوْجِي صَلَّى اللَّهُ عَلَيْكَ فَقَالَ صَلَّى اللَّهُ عَلَيْكِ وَعَلَى زَوْجِكِ ثُمَّ قَالَ ادْعُ لِي فُلَانًا ‏ ‏لِغَرِيمِي ‏ ‏الَّذِي اشْتَدَّ عَلَيَّ فِي الطَّلَبِ قَالَ فَجَاءَ فَقَالَ أَيْسِرْ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَعْنِي إِلَى الْمَيْسَرَةِ ‏ ‏طَائِفَةً مِنْ دَيْنِكَ الَّذِي عَلَى أَبِيهِ إِلَى هَذَا ‏ ‏الصِّرَامِ ‏ ‏الْمُقْبِلِ قَالَ مَا أَنَا بِفَاعِلٍ ‏ ‏وَاعْتَلَّ ‏ ‏وَقَالَ إِنَّمَا هُوَ مَالُ يَتَامَى فَقَالَ أَيْنَ ‏ ‏جَابِرٌ ‏ ‏فَقَالَ أَنَا ذَا يَا رَسُولَ اللَّهِ قَالَ كِلْ لَهُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ سَوْفَ ‏ ‏يُوَفِّيهِ فَنَظَرْتُ إِلَى السَّمَاءِ فَإِذَا الشَّمْسُ قَدْ ‏ ‏دَلَكَتْ ‏ ‏قَالَ الصَّلَاةَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَانْدَفَعُوا إِلَى الْمَسْجِدِ فَقُلْتُ قَرِّبْ أَوْعِيَتَكَ فَكِلْتُ لَهُ مِنْ الْعَجْوَةِ فَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ وَفَضَلَ لَنَا مِنْ التَّمْرِ كَذَا وَكَذَا فَجِئْتُ ‏ ‏أَسْعَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسْجِدِهِ كَأَنِّي شَرَارَةٌ فَوَجَدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ صَلَّى فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَمْ تَرَ أَنِّي كِلْتُ ‏ ‏لِغَرِيمِي ‏ ‏تَمْرَهُ فَوَفَّاهُ اللَّهُ وَفَضَلَ لَنَا مِنْ التَّمْرِ كَذَا وَكَذَا فَقَالَ أَيْنَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَجَاءَ ‏ ‏يُهَرْوِلُ ‏ ‏فَقَالَ سَلْ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏غَرِيمِهِ ‏ ‏وَتَمْرِهِ فَقَالَ مَا أَنَا بِسَائِلِهِ قَدْ عَلِمْتُ أَنَّ اللَّهَ عَزَّ وَجَلَّ سَوْفَ ‏ ‏يُوَفِّيهِ إِذْ أَخْبَرْتَ أَنَّ اللَّهَ عَزَّ وَجَلَّ سَوْفَ ‏ ‏يُوَفِّيهِ فَكَرَّرَ عَلَيْهِ هَذِهِ الْكَلِمَةَ ثَلَاثَ مَرَّاتٍ كُلُّ ذَلِكَ يَقُولُ مَا أَنَا بِسَائِلِهِ وَكَانَ لَا يُرَاجِعُ بَعْدَ الْمَرَّةِ الثَّالِثَةِ فَقَالَ يَا ‏ ‏جَابِرُ ‏ ‏مَا فَعَلَ ‏ ‏غَرِيمُكَ ‏ ‏وَتَمْرُكَ قَالَ قُلْتُ وَفَّاهُ اللَّهُ عَزَّ وَجَلَّ وَفَضَلَ لَنَا مِنْ التَّمْرِ كَذَا وَكَذَا فَرَجَعَ إِلَى امْرَأَتِهِ فَقَالَ أَلَمْ أَكُنْ نَهَيْتُكِ أَنْ تُكَلِّمِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَكُنْتَ تَظُنُّ أَنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُورِدُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتِي ثُمَّ يَخْرُجُ وَلَا أَسْأَلُهُ الصَّلَاةَ عَلَيَّ وَعَلَى زَوْجِي قَبْلَ أَنْ يَخْرُجَ ‏","","",""],[14744,14744,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَسَنِ بْنِ عَلِىٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا قَدْ ظُلِّلَ عَلَيْهِ قَالَ ‏ ‏لَيْسَ مِنْ الْبِرِّ أَنْ يَصُومَ فِي السَّفَرِ ‏","","",""],[14745,14745,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ لَهُ ‏ ‏فَضْلُ ‏ ‏أَرْضٍ أَوْ مَاءٍ فَلْيَزْرَعْهَا أَوْ لِيُزْرِعْهَا أَخَاهُ وَلَا تَبِيعُوهَا ‏ ‏فَسَأَلْتُ ‏ ‏سَعِيدًا ‏ ‏مَا لَا تَبِيعُوهَا ‏ ‏الْكِرَاءُ ‏ ‏قَالَ نَعَمْ ‏","","",""],[14746,14746,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏كَعْبُ بْنَ عُجْرَةَ ‏ ‏أُعِيذُكَ بِاللَّهِ مِنْ إِمَارَةِ ‏ ‏السُّفَهَاءِ ‏ ‏قَالَ وَمَا ذَاكَ يَا رَسُولَ اللَّهِ قَالَ أُمَرَاءٌ سَيَكُونُونَ مِنْ بَعْدِي مَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِحَدِيثِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسُوا مِنِّي وَلَسْتُ مِنْهُمْ وَلَمْ يَرِدُوا عَلَيَّ الْحَوْضَ وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَلَمْ يُصَدِّقْهُمْ بِحَدِيثِهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ فَأُولَئِكَ مِنِّي وَأَنَا مِنْهُمْ وَأُولَئِكَ يَرِدُونَ عَلَيَّ الْحَوْضَ يَا ‏ ‏كَعْبُ بْنَ عُجْرَةَ ‏ ‏الصَّلَاةُ قُرْبَانٌ وَالصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏وَالصَّدَقَةُ ‏ ‏تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ يَا ‏ ‏كَعْبُ بْنَ عُجْرَةَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ مَنْ نَبَتَ لَحْمُهُ مِنْ ‏ ‏سُحْتٍ ‏ ‏النَّارُ أَوْلَى بِهِ يَا ‏ ‏كَعْبُ بْنَ عُجْرَةَ ‏ ‏النَّاسُ ‏ ‏غَادِيَانِ ‏ ‏فَغَادٍ بَائِعٌ نَفْسَهُ ‏ ‏وَمُوبِقٌ ‏ ‏رَقَبَتَهُ وَغَادٍ مُبْتَاعٌ نَفْسَهُ وَمُعْتِقٌ رَقَبَتَهُ ‏","","",""],[14747,14747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ لَيْلًا فَلَا يَطْرُقَنَّ أَهْلَهُ طُرُوقًا ‏","","",""],[14748,14748,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ رَاشِدٍ ‏ ‏سَنَةَ مِائَةٍ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُجَصَّصَ ‏ ‏الْقُبُورُ أَوْ ‏ ‏يُبْنَى عَلَيْهَا ‏","","",""],[14749,14749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ رَاشِدٍ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَجُلٌ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏بَنِي عُذْرَةَ ‏ ‏فَقُبِرَ لَيْلًا ‏ ‏فَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُقْبَرَ الرَّجُلُ لَيْلًا حَتَّى يُصَلَّى عَلَيْهِ إِلَّا أَنْ ‏ ‏يَضْطَرُّوا إِلَى ذَلِكَ ‏","","",""],[14750,14750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ كَأَنِّي أَتَيْتُ بِكُتْلَةِ تَمْرٍ فَعَجَمْتُهَا فِي فَمِي فَوَجَدْتُ فِيهَا نَوَاةً آذَتْنِي فَلَفَظْتُهَا ثُمَّ أَخَذْتُ أُخْرَى فَعَجَمْتُهَا فَوَجَدْتُ فِيهَا نَوَاةً فَلَفَظْتُهَا ثُمَّ أَخَذْتُ أُخْرَى فَعَجَمْتُهَا فَوَجَدْتُ فِيهَا نَوَاةً فَلَفَظْتُهَا فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏دَعْنِي فَلْأَعْبُرْهَا قَالَ قَالَ اعْبُرْهَا قَالَ هُوَ جَيْشُكَ الَّذِي بَعَثْتَ يَسْلَمُ وَيَغْنَمُ فَيَلْقَوْنَ رَجُلًا فَيَنْشُدُهُمْ ‏ ‏ذِمَّتَكَ ‏ ‏فَيَدَعُونَهُ ثُمَّ يَلْقَوْنَ رَجُلًا فَيَنْشُدُهُمْ ‏ ‏ذِمَّتَكَ ‏ ‏فَيَدَعُونَهُ ثُمَّ يَلْقَوْنَ رَجُلًا فَيَنْشُدُهُمْ ‏ ‏ذِمَّتَكَ ‏ ‏فَيَدَعُونَهُ قَالَ كَذَلِكَ قَالَ الْمَلَكُ ‏","","",""],[14751,14751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالشُّفْعَةِ ‏ ‏فِي كُلِّ مَا لَمْ يُقْسَمْ فَإِذَا وَقَعَتْ ‏ ‏الْحُدُودُ ‏ ‏وَصُرِّفَتْ ‏ ‏الطُّرُقُ فَلَا ‏ ‏شُفْعَةَ ‏","","",""],[14752,14752,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏أَيُّمَا رَجُلٍ أُعْمِرَ عُمْرَى لَهُ وَلِعَقِبِهِ فَقَالَ قَدْ أَعْطَيْتُكَهَا ‏ ‏وَعَقِبَكَ ‏ ‏مَا بَقِيَ مِنْكُمْ أَحَدٌ فَإِنَّمَا هِيَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لِمَنْ أَعْطَاهَا ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏لِمَنْ أُعْطِيَهَا ‏ ‏وَإِنَّهَا لَا تَرْجِعُ إِلَى صَاحِبِهَا مِنْ أَجْلِ أَنَّهُ أَعْطَاهَا عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ ‏","","",""],[14753,14753,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏ضُحًى وَرَمَى فِي سَائِرِ أَيَّامِ التَّشْرِيقِ بَعْدَمَا زَالَتْ الشَّمْسُ ‏","","",""],[14754,14754,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏أَنْبَأَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا عَلَى أَخٍ لَكُمْ مَاتَ بِغَيْرِ أَرْضِكُمْ قَالُوا مَنْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏النَّجَاشِيُّ أَصْحَمَةُ ‏ ‏قَالَ ‏ ‏فَقُلْتُ فَصَفَفْتُمْ عَلَيْهِ ‏ ‏قَالَ ‏ ‏نَعَمْ كُنْتُ فِي الصَّفِّ الثَّالِثِ ‏","","",""],[14755,14755,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏مُثَنَّى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِهِ إِلَى مَنْزِلِهِ فَلَمَّا انْتَهَى قَالَ مَا مِنْ غَدَاءٍ ‏ ‏أَوْ عَشَاءٍ شَكَّ ‏ ‏طَلْحَةُ ‏ ‏قَالَ فَأَخْرَجُوا ‏ ‏فَلْقًا ‏ ‏مِنْ خُبْزٍ قَالَ مَا مِنْ ‏ ‏أُدْمٍ ‏ ‏قَالُوا لَا إِلَّا شَيْءٌ مِنْ خَلٍّ قَالَ ‏ ‏أَدْنِيهِ ‏ ‏فَإِنَّ الْخَلَّ نِعْمَ ‏ ‏الْأُدْمُ ‏ ‏هُوَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏مَا زِلْتُ أُحِبُّ الْخَلَّ مُنْذُ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏طَلْحَةُ ‏ ‏مَا زِلْتُ أُحِبُّ الْخَلَّ مُنْذُ سَمِعْتُهُ مِنْ ‏ ‏جَابِرٍ ‏","","",""],[14756,14756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَأَيُّمَا رَجُلٍ مِنْ الْمُسْلِمِينَ سَبَبْتُهُ أَوْ جَلَدْتُهُ أَوْ لَعَنْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَأَجْرًا ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏مِثْلَهُ غَيْرَ أَنَّهُ قَالَ زَكَاةً وَرَحْمَةً ‏","","",""],[14757,14757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيَسْتَجْمِرْ ‏ ‏ثَلَاثًا ‏","","",""],[14758,14758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ وَلَا مُسْلِمَةٍ وَلَا مُؤْمِنٍ وَلَا مُؤْمِنَةٍ يُصِيبُهُ مَرَضٌ إِلَّا حَطَّ اللَّهُ عَنْهُ مِنْ خَطَايَاهُ ‏","","",""],[14759,14759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَاعِيلَ ‏ ‏قِرَاءَةً عَلَيْنَا مِنْ كِتَابِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فَقُدَّ قَمِيصُهُ مِنْ جَيْبِهِ حَتَّى أَخْرَجَهُ مِنْ رِجْلَيْهِ فَنَظَرَ الْقَوْمُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي أَمَرْتُ ‏ ‏بِبُدْنِي ‏ ‏الَّتِي بَعَثْتُ بِهَا أَنْ ‏ ‏تُقَلَّدَ ‏ ‏الْيَوْمَ ‏ ‏وَتُشْعَرَ ‏ ‏الْيَوْمَ عَلَى مَاءِ كَذَا وَكَذَا فَلَبِسْتُ قَمِيصًا وَنَسِيتُ فَلَمْ أَكُنْ أُخْرِجُ قَمِيصِي مِنْ رَأْسِي وَكَانَ قَدْ بَعَثَ ‏ ‏بِبُدْنِهِ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَقَامَ ‏ ‏بِالْمَدِينَةِ ‏","","",""],[14760,14760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَفْوَانَ ‏ ‏وَسَمَّاهُ فِي غَيْرِ هَذَا الْحَدِيثِ ‏ ‏عَبْدَ اللَّهِ بْنَ سَعِيدِ بْنِ عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏زَعَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ ثُومًا أَوْ بَصَلًا فَلْيَعْتَزِلْنَا ‏ ‏أَوْ قَالَ فَلْيَعْتَزِلْ مَسْجِدَنَا ‏ ‏وَلْيَقْعُدْ فِي بَيْتِهِ ‏ ‏آخِرُ مُسْنَدِ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[14761,14761,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏زَوَّجَنِي أَبِي فِي ‏ ‏إِمَارَةِ ‏ ‏عُثْمَانَ ‏ ‏فَدَعَا ‏ ‏نَفَرًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏صَفْوَانُ بْنُ أُمَيَّةَ ‏ ‏وَهُوَ شَيْخٌ كَبِيرٌ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏انْهَسُوا ‏ ‏اللَّحْمَ ‏ ‏نَهْسًا ‏ ‏فَإِنَّهُ أَهْنَأُ ‏ ‏وَأَمْرَأُ ‏ ‏أَوْ أَشْهَى ‏ ‏وَأَمْرَأُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الشَّكُّ مِنِّي أَوْ مِنْهُ ‏","","",""],[14762,14762,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ يَعْنِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ يَعْنِي النَّهْدِيَّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏الطَّاعُونُ ‏ ‏وَالْبَطْنُ ‏ ‏وَالْغَرَقُ ‏ ‏وَالنُّفَسَاءُ ‏ ‏شَهَادَةٌ ‏ ‏حَدَّثَنَا ‏ ‏بِهِ ‏ ‏أَبُو عُثْمَانَ ‏ ‏مِرَارًا وَقَدْ رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّةً ‏","","",""],[14763,14763,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏أُمَيَّةَ بْنِ صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَعَارَ ‏ ‏مِنْهُ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏أَدْرَاعًا فَقَالَ أَغَصْبًا يَا ‏ ‏مُحَمَّدُ ‏ ‏فَقَالَ بَلْ ‏ ‏عَارِيَةٌ ‏ ‏مَضْمُونَةٌ قَالَ فَضَاعَ بَعْضُهَا فَعَرَضَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَضْمَنَهَا لَهُ فَقَالَ أَنَا الْيَوْمَ يَا رَسُولَ اللَّهِ فِي الْإِسْلَامِ أَرْغَبُ ‏","","",""],[14764,14764,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏صَفْوَانَ بْنَ أُمَيَّةَ بْنِ خَلَفٍ ‏ ‏قِيلَ لَهُ هَلَكَ مَنْ لَمْ يُهَاجِرْ قَالَ فَقُلْتُ لَا أَصِلُ إِلَى أَهْلِي حَتَّى آتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَكِبْتُ رَاحِلَتِي فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏زَعَمُوا أَنَّهُ هَلَكَ مَنْ لَمْ يُهَاجِرْ قَالَ كَلَّا ‏ ‏أَبَا وَهْبٍ ‏ ‏فَارْجِعْ إِلَى أَبَاطِحِ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَبَيْنَمَا أَنَا رَاقِدٌ إِذْ جَاءَ السَّارِقُ فَأَخَذَ ثَوْبِي مِنْ تَحْتِ رَأْسِي فَأَدْرَكْتُهُ فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنَّ هَذَا سَرَقَ ثَوْبِي فَأَمَرَ بِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُقْطَعَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ لَيْسَ هَذَا أَرَدْتُ هُوَ عَلَيْهِ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ فَهَلَّا قَبْلَ أَنْ تَأْتِيَنِي بِهِ ‏","","",""],[14765,14765,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏أَعْطَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏وَإِنَّهُ لَأَبْغَضُ النَّاسِ إِلَيَّ فَمَا زَالَ يُعْطِينِي حَتَّى صَارَ وَإِنَّهُ أَحَبُّ النَّاسِ إِلَيَّ ‏","","",""],[14766,14766,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ مُرَقَّعٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏أَنَّ رَجُلًا سَرَقَ ‏ ‏بُرْدَهُ ‏ ‏فَرَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِقَطْعِهِ فَقَالَ يَا رَسُولَ اللَّهِ قَدْ تَجَاوَزْتُ عَنْهُ قَالَ فَلَوْلَا كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ يَا ‏ ‏أَبَا وَهْبٍ ‏ ‏فَقَطَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14767,14767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏أَنَّهُ قِيلَ لَهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مَنْ هَاجَرَ قَالَ فَقُلْتُ لَا أَدْخُلُ مَنْزِلِي حَتَّى آتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْأَلَهُ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ هَذَا سَرَقَ ‏ ‏خَمِيصَةً ‏ ‏لِي لِرَجُلٍ مَعَهُ ‏ ‏فَأَمَرَ بِقَطْعِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ فَإِنِّي قَدْ وَهَبْتُهَا لَهُ قَالَ فَهَلَّا قَبْلَ أَنْ تَأْتِيَنِي بِهِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُمْ يَقُولُونَ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مَنْ هَاجَرَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا هِجْرَةَ بَعْدَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَلَكِنْ جِهَادٌ وَنِيَّةٌ فَإِذَا ‏ ‏اسْتُنْفِرْتُمْ ‏ ‏فَانْفِرُوا ‏","","",""],[14768,14768,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ يَعْنِي النَّهْدِيَّ ‏ ‏عَنْ ‏ ‏عَامِرٍ يَعْنِي ابْنَ مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطَّاعُونُ شَهَادَةٌ ‏ ‏وَالْغَرَقُ ‏ ‏شَهَادَةٌ ‏ ‏وَالْبَطْنُ ‏ ‏شَهَادَةٌ ‏ ‏وَالنُّفَسَاءُ ‏ ‏شَهَادَةٌ ‏","","",""],[14769,14769,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏الطَّاعُونُ ‏ ‏وَالْبَطْنُ ‏ ‏وَالْغَرَقُ ‏ ‏وَالنُّفَسَاءُ ‏ ‏شَهَادَةٌ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏بِهِ ‏ ‏يَعْنِي ‏ ‏أَبَا عُثْمَانَ ‏ ‏مِرَارًا وَرَفَعَهُ مَرَّةً إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14770,14770,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏صَفْوَانُ بْنُ أُمَيَّةَ ‏ ‏رَآنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا آخُذُ اللَّحْمَ عَنْ الْعَظْمِ بِيَدِي فَقَالَ يَا ‏ ‏صَفْوَانُ ‏ ‏قُلْتُ لَبَّيْكَ قَالَ ‏ ‏قَرِّبْ اللَّحْمَ مِنْ فِيكَ فَإِنَّهُ أَهْنَأُ ‏ ‏وَأَمْرَأُ ‏","","",""],[14771,14771,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ قَرْمٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ ‏ ‏ابْنِ أُخْتِ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏كُنْتُ نَائِمًا فِي الْمَسْجِدِ عَلَى ‏ ‏خَمِيصَةٍ ‏ ‏لِي فَسُرِقَتْ فَأَخَذْنَا السَّارِقَ فَرَفَعْنَاهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِقَطْعِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَفِي ‏ ‏خَمِيصَةٍ ‏ ‏ثَمَنُ ثَلَاثِينَ دِرْهَمًا أَنَا أَهَبُهَا لَهُ أَوْ أَبِيعُهَا لَهُ قَالَ فَهَلَّا كَانَ قَبْلَ أَنْ تَأْتِيَنِي بِهِ ‏","","",""],[14772,14772,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ جَعْفَرِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ يَأْتِينِي الرَّجُلُ يَسْأَلُنِي الْبَيْعَ لَيْسَ عِنْدِي مَا أَبِيعُهُ ثُمَّ أَبِيعُهُ مِنْ السُّوقِ فَقَالَ ‏ ‏لَا تَبِعْ مَا لَيْسَ عِنْدَكَ ‏","","",""],[14773,14773,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَنْ لَا ‏ ‏أَخِرَّ ‏ ‏إِلَّا قَائِمًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ الرَّجُلُ يَسْأَلُنِي الْبَيْعَ وَلَيْسَ عِنْدِي أَفَأَبِيعُهُ قَالَ ‏ ‏لَا تَبِعْ مَا لَيْسَ عِنْدَكَ ‏","","",""],[14774,14774,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَبِيعَ مَا لَيْسَ عِنْدِي ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏أَوْ قَالَ سِلْعَةً لَيْسَتْ عِنْدِي ‏","","",""],[14775,14775,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا فَإِنْ صَدَقَا وَبَيَّنَا رُزِقَا بَرَكَةَ بَيْعِهِمَا وَإِنْ كَذَبَا وَكَتَمَا ‏ ‏مُحِقَ ‏ ‏بَرَكَةُ بَيْعِهِمَا ‏","","",""],[14776,14776,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ يُطْلَبُ مِنِّي الْمَتَاعُ وَلَيْسَ عِنْدِي أَفَأَبِيعُهُ لَهُ قَالَ ‏ ‏لَا تَبِعْ مَا لَيْسَ عِنْدَكَ ‏","","",""],[14777,14777,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي الدَّسْتُوَائِيَّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏أَنَّ ‏ ‏يُوسُفَ بْنَ مَاهَكَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَصْمَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أَشْتَرِي بُيُوعًا فَمَا يَحِلُّ لِي مِنْهَا وَمَا يُحَرَّمُ عَلَيَّ قَالَ ‏ ‏فَإِذَا اشْتَرَيْتَ بَيْعًا فَلَا تَبِعْهُ حَتَّى تَقْبِضَهُ ‏","","",""],[14778,14778,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خَيْرَ ‏ ‏الصَّدَقَةِ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[14779,14779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ مِنْ ‏ ‏عَتَاقَةٍ ‏ ‏وَصِلَةِ رَحِمٍ هَلْ لِي فِيهَا أَجْرٌ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏مِنْ خَيْرٍ ‏","","",""],[14780,14780,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏وَالتَّحَنُّثُ التَّعَبُّدُ ‏","","",""],[14781,14781,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ بَشِيرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الصَّدَقَاتِ ‏ ‏أَيُّهَا أَفْضَلُ قَالَ ‏ ‏عَلَى ذِي الرَّحِمِ ‏ ‏الْكَاشِحِ ‏","","",""],[14782,14782,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ جُنْدُبٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْمَالِ فَأَلْحَفْتُ فَقَالَ يَا ‏ ‏حَكِيمُ ‏ ‏مَا أَكْثَرَ مَسْأَلَتَكَ يَا ‏ ‏حَكِيمُ ‏ ‏إِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةٌ وَإِنَّمَا هُوَ مَعَ ذَلِكَ أَوْسَاخُ أَيْدِي النَّاسِ وَيَدُ اللَّهِ فَوْقَ يَدِ الْمُعْطِي وَيَدُ الْمُعْطِي فَوْقَ يَدِ الْمُعْطَى وَأَسْفَلُ الْأَيْدِي يَدُ الْمُعْطَى ‏","","",""],[14783,14783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا وَإِنْ كَذَبَا وَكَتَمَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا ‏","","",""],[14784,14784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبَّ رَجُلٍ فِي النَّاسِ إِلَيَّ فِي الْجَاهِلِيَّةِ فَلَمَّا تَنَبَّأَ وَخَرَجَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏شَهِدَ ‏ ‏حَكِيمُ بْنُ حِزَامٍ ‏ ‏الْمَوْسِمَ وَهُوَ كَافِرٌ فَوَجَدَ ‏ ‏حُلَّةً ‏ ‏لِذِي يَزَنَ ‏ ‏تُبَاعُ فَاشْتَرَاهَا بِخَمْسِينَ دِينَارًا لِيُهْدِيَهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَدِمَ بِهَا عَلَيْهِ ‏ ‏الْمَدِينَةَ ‏ ‏فَأَرَادَهُ عَلَى قَبْضِهَا هَدِيَّةً فَأَبَى ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ ‏ ‏إِنَّا لَا نَقْبَلُ شَيْئًا مِنْ الْمُشْرِكِينَ وَلَكِنْ إِنْ شِئْتَ أَخَذْنَاهَا بِالثَّمَنِ فَأَعْطَيْتُهُ حِينَ أَبَى عَلَيَّ الْهَدِيَّةَ ‏","","",""],[14785,14785,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا ‏ ‏قَالَ وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏الْخِيَارُ ‏ ‏ثَلَاثُ مَرَّاتٍ فَإِنْ صَدَقَا وَبَيَّنَا فَعَسَى أَنْ يَرْبَحَا رِبْحًا وَإِنْ كَذَبَا وَكَتَمَا ‏ ‏مُحِقَتْ ‏ ‏بَرَكَةُ بَيْعِهِمَا ‏","","",""],[14786,14786,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا وَإِنْ كَذَبَا وَكَتَمَا ‏ ‏مُحِقَ ‏ ‏بَرَكَةُ بَيْعِهِمَا ‏","","",""],[14787,14787,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِشَامَ بْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏مَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ ‏ ‏يَسْتَعْفِفْ ‏ ‏يُعِفَّهُ ‏ ‏اللَّهُ ‏","","",""],[14788,14788,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا قَالَ فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا وَإِنْ كَذَبَا وَكَتَمَا ‏ ‏مُحِقَتْ ‏ ‏بَرَكَةُ بَيْعِهِمَا ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏مُحِقَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏مِثْلِهِ قَالَ مَا لَمْ يَتَفَرَّقَا ‏","","",""],[14789,14789,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏صَفْوَانَ بْنَ مَوْهَبٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ يَأْتِنِي ‏ ‏أَوَلَمْ يَبْلُغْنِي أَوْ كَمَا شَاءَ اللَّهُ مِنْ ذَلِكَ ‏ ‏أَنَّكَ تَبِيعُ الطَّعَامَ قَالَ بَلَى يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَبِعْ طَعَامًا حَتَّى تَشْتَرِيَهُ ‏ ‏وَتَسْتَوْفِيَهُ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيْضًا ‏ ‏عَبْدُ اللَّهِ بْنُ عَصْمَةَ الْجُشَمِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏يُحَدِّثُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14790,14790,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ حِزَامٍ ‏ ‏أَنَّهُ مَرَّ بِأُنَاسٍ مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏قَدْ أُقِيمُوا فِي الشَّمْسِ ‏ ‏بِالشَّامِ ‏ ‏فَقَالَ مَا هَؤُلَاءِ قَالُوا بَقِيَ عَلَيْهِمْ شَيْءٌ مِنْ ‏ ‏الْخَرَاجِ ‏ ‏فَقَالَ إِنِّي أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُعَذِّبُ يَوْمَ الْقِيَامَةِ الَّذِينَ يُعَذِّبُونَ النَّاسَ ‏ ‏قَالَ ‏ ‏وَأَمِيرُ النَّاسِ يَوْمَئِذٍ ‏ ‏عُمَيْرُ بْنُ سَعْدٍ ‏ ‏عَلَى ‏ ‏فِلَسْطِينَ ‏ ‏قَالَ فَدَخَلَ عَلَيْهِ فَحَدَّثَهُ فَخَلَّى سَبِيلَهُمْ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَكِيمٍ ‏ ‏أَنَّهُ مَرَّ ‏ ‏بِالشَّامِ ‏ ‏عَلَى قَوْمٍ مِنْ ‏ ‏الْأَنْبَاطِ ‏ ‏وَقَدْ أُقِيمُوا فِي الشَّمْسِ فَذَكَرَ مَعْنَاهُ ‏","","",""],[14791,14791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَهِشَامِ بْنِ عُرْوَةَ ‏ ‏أَنَّهُمَا حَدَّثَاهُ عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏هِشَامَ بْنَ حَكِيمٍ ‏ ‏رَأَى نَاسًا مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏قِيَامًا فِي الشَّمْسِ فَقَالَ مَا هَؤُلَاءِ فَقَالُوا مِنْ أَهْلِ ‏ ‏الْجِزْيَةِ ‏ ‏فَدَخَلَ عَلَى ‏ ‏عُمَيْرِ بْنِ سَعْدٍ ‏ ‏وَكَانَ عَلَى طَائِفَةِ ‏ ‏الشَّامِ ‏ ‏فَقَالَ ‏ ‏هِشَامٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ عَذَّبَ النَّاسَ فِي الدُّنْيَا عَذَّبَهُ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ ‏فَقَالَ ‏ ‏عُمَيْرٌ ‏ ‏خَلُّوا عَنْهُمْ ‏","","",""],[14792,14792,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنِي ‏ ‏شُرَيْحُ بْنُ عُبَيْدٍ الْحَضْرَمِيُّ ‏ ‏وَغَيْرُهُ ‏ ‏قَالَ ‏ ‏جَلَدَ ‏ ‏عِيَاضُ بْنُ غَنْمٍ ‏ ‏صَاحِبَ دَارِيَا حِينَ فُتِحَتْ فَأَغْلَظَ لَهُ ‏ ‏هِشَامُ بْنُ حَكِيمٍ ‏ ‏الْقَوْلَ حَتَّى غَضِبَ ‏ ‏عِيَاضٌ ‏ ‏ثُمَّ مَكَثَ ‏ ‏لَيَالِيَ فَأَتَاهُ ‏ ‏هِشَامُ بْنُ حَكِيمٍ ‏ ‏فَاعْتَذَرَ إِلَيْهِ ثُمَّ قَالَ ‏ ‏هِشَامٌ ‏ ‏لِعِيَاضٍ ‏ ‏أَلَمْ تَسْمَعْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَشَدِّ النَّاسِ عَذَابًا أَشَدَّهُمْ عَذَابًا فِي الدُّنْيَا لِلنَّاسِ ‏ ‏فَقَالَ ‏ ‏عِيَاضُ بْنُ غَنْمٍ ‏ ‏يَا ‏ ‏هِشَامُ بْنَ حَكِيمٍ ‏ ‏قَدْ سَمِعْنَا مَا سَمِعْتَ وَرَأَيْنَا مَا رَأَيْتَ أَوَلَمْ تَسْمَعْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ أَرَادَ أَنْ يَنْصَحَ لِسُلْطَانٍ بِأَمْرٍ فَلَا يُبْدِ لَهُ عَلَانِيَةً وَلَكِنْ لِيَأْخُذْ بِيَدِهِ فَيَخْلُوَ بِهِ فَإِنْ قَبِلَ مِنْهُ فَذَاكَ وَإِلَّا كَانَ قَدْ أَدَّى الَّذِي عَلَيْهِ لَهُ ‏ ‏وَإِنَّكَ يَا ‏ ‏هِشَامُ ‏ ‏لَأَنْتَ الْجَرِيءُ إِذْ تَجْتَرِئُ عَلَى سُلْطَانِ اللَّهِ فَهَلَّا خَشِيتَ أَنْ يَقْتُلَكَ السُّلْطَانُ فَتَكُونَ قَتِيلَ سُلْطَانِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏","","",""],[14793,14793,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّهُ ‏ ‏بَلَغَهُ ‏ ‏أَنَّ ‏ ‏عِيَاضَ بْنَ غَنْمٍ ‏ ‏رَأَى نَبَطًا يُشَمَّسُونَ فِي ‏ ‏الْجِزْيَةِ ‏ ‏فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ النَّاسَ فِي الدُّنْيَا ‏","","",""],[14794,14794,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏هِشَامَ بْنَ حَكِيمِ بْنِ حِزَامٍ ‏ ‏وَجَدَ ‏ ‏عِيَاضَ بْنَ غَنْمٍ ‏ ‏وَهُوَ عَلَى ‏ ‏حِمْصَ ‏ ‏يُشَمِّسُ نَاسًا مِنْ ‏ ‏النَّبَطِ ‏ ‏فِي أَدَاءِ ‏ ‏الْجِزْيَةِ ‏ ‏فَقَالَ لَهُ ‏ ‏هِشَامٌ ‏ ‏مَا هَذَا يَا ‏ ‏عِيَاضُ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ النَّاسَ فِي الدُّنْيَا ‏","","",""],[14795,14795,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عِيَاضَ بْنَ غَنْمٍ ‏ ‏وَهِشَامَ بْنَ حَكِيمِ بْنِ حِزَامٍ ‏ ‏مَرَّا بِعَامِلِ ‏ ‏حِمْصَ ‏ ‏وَهُوَ يُشَمِّسُ ‏ ‏أَنْبَاطًا ‏ ‏فِي الشَّمْسِ فَقَالَ أَحَدُهُمَا لِلْعَامِلِ مَا هَذَا يَا فُلَانُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ النَّاسَ فِي الدُّنْيَا ‏","","",""],[14796,14796,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏رَبِيعِ بْنِ سَبْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ مُتْعَةِ النِّسَاءِ يَوْمَ الْفَتْحِ ‏","","",""],[14797,14797,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أُمَيَّةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏الْمُتْعَةَ ‏ ‏مُتْعَةَ ‏ ‏النِّسَاءِ ‏ ‏فَقَالَ ‏ ‏رَبِيعُ بْنُ سَبْرَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏يَنْهَى عَنْ نِكَاحِ ‏ ‏الْمُتْعَةِ ‏","","",""],[14798,14798,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ الرَّبِيعِ بْنِ سَبْرَةَ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَلَغَ الْغُلَامُ سَبْعَ سِنِينَ أُمِرَ بِالصَّلَاةِ فَإِذَا بَلَغَ عَشْرًا ضُرِبَ عَلَيْهَا ‏","","",""],[14799,14799,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ الرَّبِيعِ بْنِ سَبْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلْيَسْتَتِرْ لِصَلَاتِهِ وَلَوْ ‏ ‏بِسَهْمٍ ‏","","",""],[14800,14800,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ الرَّبِيعِ بْنِ سَبْرَةَ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُصَلَّى فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ وَرَخَّصَ أَنْ يُصَلَّى فِي ‏ ‏مُرَاحِ ‏ ‏الْغَنَمِ ‏","","",""]];
